def symbol_address(name: str) -> int:
    """Read a variable's data-space address from the linker symbol file.

    This mdb build cannot write a C variable by name (`write g_x 1` fails with
    `For input string: "<addr> "`), so fault injection / the diagnostic trigger has to go through
    `write /r 0x<addr> <byte>` instead. Addresses move on every rebuild, so parse `.sym` at run
    time (see the build-test skill and test_first_dit.py).
    """
    sym = IMAGE_DIR / "default.sym"
    if not sym.exists():
        sys.exit(f"error: {sym} not found - build the firmware first")
    for line in sym.read_text().splitlines():
        fields = line.split()
        if fields and fields[0] == f"_{name}":
            return int(fields[1], 16)
    sys.exit(f"error: symbol {name} not found in {sym}")


def record_stimulus(script: str) -> None:
    """Fill `STIMULUS` from a generated MDB script: what the counter was fed, and when.

    Decoding the emitted `TMR1H`/`TMR1L` pair is exact, because the injection is the inverse of the
    firmware's own scaling (`counts = kHz * 1000 / 400`), and it needs no marker line in the script
    - which matters, because `.mdb` files have no comment syntax that is safe to rely on.
    """
    STIMULUS.clear()
    instructions = 0
    pending_high = None
    for raw in script.splitlines():
        line = raw.strip()
        match = STEPI_RE.match(line)
        if match:
            instructions += int(match.group(1))
            continue
        if line.startswith("write TMR1H"):
            pending_high = int(line.split()[-1], 16) << 8
        elif line.startswith("write TMR1L") and pending_high is not None:
            counts = pending_high | int(line.split()[-1], 16)
            STIMULUS.append((instructions, int(round(counts * 400 / 1000.0))))
            pending_high = None


def stimulus_spans(samples=None, entries=None):
    """`STIMULUS` as `[(start_ms, end_ms, khz)]`, merging consecutive injections of one frequency.

    Spans, not points: the counter is fed the same value every 5 ms while a band is held, and a step
    line one span long is what tells the reader "this is what went in" instead of peppering the lane
    with hundreds of identical markers.
    """
    entries = STIMULUS if entries is None else entries
    if not entries:
        return []
    ms = SECONDS_PER_INSTRUCTION * 1000
    last_instr = samples[-1][0] if samples else entries[-1][0]
    spans = []
    for index, (instructions, freq_khz) in enumerate(entries):
        end_instr = entries[index + 1][0] if index + 1 < len(entries) else last_instr
        if end_instr <= instructions:
            continue
        if spans and spans[-1][2] == freq_khz:
            spans[-1][1] = end_instr * ms
        else:
            spans.append([instructions * ms, end_instr * ms, freq_khz])
    return [tuple(span) for span in spans]


# Code generated by MCHP Chatbot
def build_script(trip_name=None) -> str:
    temperature_trip = trip_name == "TEMPERATURE"
    lines = [f"device {DEVICE}", "hwtool sim", f"program {ELF_PATH}"]
    # What the harness feeds the frequency counter, position by position. The graphs need it: the
    # measured frequency alternates between the injected value and 0 (the firmware resets TMR1 on
    # every 10 ms gate and nothing else clocks it in the model), so without the stimulus beside it
    # the lane looks like a fault rather than a sampling artefact - and, when the harness walks
    # through bands, it looks like a wildly unstable counter (user instruction, 2026-09-25: *"put
    # which frequency you are inputting to the freq counter so I can see why its changing so
    # much"*). Rebuilt from the generated script at the end, so nothing here has to track it.
    STIMULUS.clear()
    # --- Setup: Set all analog and relevant inputs to safe values ---
    lines += [
        "write pin RA0 0v", "write pin RA1 0v", "write pin RA2 0v", "write pin RA3 0v",
        "write pin RA5 2.5v", "write pin RB1 0v", "write pin RB2 0v", "write pin RB3 0v", "write pin RB4 0v",
        "write pin RC2 5v", "write pin RB0 5v", "write pin RB6 5v"
    ]

    def sample(release=False, adc=None):
        """One sample of the firmware's pins and state.

        `release=True` is the LEAN unkey sample (pins + RELEASE_SAMPLE_VARS), taken at 1 ms while the
        amplifier unwinds - see RELEASE_SAMPLE_VARS for why that window needs it.

        `adc=None` means "print the ADC pins only if this scenario asserts ADC readings". Every sample
        costs one MDB command per printed item and the model charges SIMULATED time for each, so the
        eight ADC pins are pure cost in a scenario whose assertions never look at them (base,
        FREQ_CTR, FREQ_CTR_FAIL - they drive no bridge stimulus and read no ADC value).
        """
        if adc is None:
            adc = trip_name not in (None, "FREQ_CTR", "FREQ_CTR_FAIL") and trip_name not in SELFTEST_SCENARIOS
        for pin in PINS:
            lines.append(f"print pin {pin}")
        if release:
            for var in RELEASE_SAMPLE_VARS:
                lines.append(f"print {var}")
            return
        if adc:
            for pin in ADC_PINS:
                lines.append(f"print pin {pin}")
        for var in STATE_VARS:
            lines.append(f"print {var}")
        if trip_name == "FREQ_CTR":
            # Counter registers, for the FREQ_CTR investigation only. `print TMR1`/`print T1CON` do
            # not match parse_trace's grammar (pins are `R[A-Z]\d+`, state is `g_...`), so they are
            # extra evidence in the transcript and change no sample. They answer the one question the
            # derived values cannot: is the injected count actually IN the register when the firmware
            # reads it (TMR1), and is the timer still running (T1CON ON bit) while keyed?
            lines.append("print TMR1")
            lines.append("print T1CON")

    def write_tmr1_count(freq_khz):
        """Inject the Timer1 count that the firmware's own scaling maps to freq_khz.

        Why this is register injection instead of a real clock on T1CKI: the MPLAB X
        simulator does not implement Timer1's external clock selection. It warns
        "W0106-SIM: This device only has partial support for TMR1 peripheral ... timer
        clock selection is not implemented". Driving RD1 with an SCL stimulus
        (mdb `stim`, verified 2026-09-21) leaves TMR1L/TMR1H at 0 even though the pin
        is actively driven (print pin RD1 reports HIGH/Din) and T1CON reads 0x27
        (TMR1ON, RD16, nSYNC, CKPS=1:4, CS=00=T1CKI).

        So a true end-to-end RF frequency-counter test is not possible in the simulator.
        Writing the count exercises the frequency maths, classification, band-select
        outputs and the TX lock logic, but it does NOT cover the T1CKI pin, the PPS
        routing, the 1:4 prescaler, or the Timer1 overflow path.

        counts = freq_khz * 1000 / 400  (inverse of the firmware's pulses*2/5)
        """
        total_counts = int(round((freq_khz * 1000.0) / 400.0))
        if total_counts > 0xFFFF:
            raise ValueError(f"{freq_khz} kHz cannot be represented by a 16-bit Timer1 write")
        # Atomic injection: halt Timer1, write both bytes, restart - so the firmware's 10 ms
        # freq_counter_tick_10ms() cannot read a torn register (TMR1L new + TMR1H old) mid-write.
        # BYTE ORDER (root cause of the 20m blocker): T1CON 0x27 has RD16 set, so a write to TMR1H
        # is buffered and only committed when TMR1L is written. Writing L before H therefore drops
        # the high byte, so only counts <= 0xFF survived: 7000 kHz (0x445C) truncated to 0x005C =
        # 92 pulses = 37 kHz (band 1, the no-signal default) and 14000 kHz (0x88B8) to 0x00B8 =
        # 184 pulses = 73 kHz, so no injected band above ~100 kHz ever classified. Write TMR1H FIRST.
        # This truncation is also what produced the "garbage readings" (freq=73/8/36) once blamed on
        # a race with the running gate.
        # T1CON running value is 0x27 (ON+RD16+NOT_SYNC+CKPS=2, per freq_counter_init); stop is 0x26.
        if TMR1_STOP_BRACKET:
            lines.append("write T1CON 0x26")
        lines.append(f"write TMR1H 0x{(total_counts >> 8) & 0xFF:02X}")
        lines.append(f"write TMR1L 0x{total_counts & 0xFF:02X}")
        # ALWAYS leave the timer RUNNING, whether or not it was stopped first. The firmware's
        # read_counter_atomically() stops Timer1, reads it, then restarts it **only if it was running
        # when the read began** - so a read that lands while the harness has it stopped leaves it
        # stopped for good, and a stopped TMR1 stops accepting the injected count. That is the
        # sticky-zero failure the FREQ_CTR scenario keeps showing (a whole band reading 0 while the
        # harness injects every 5 ms), and it is why disabling the stop bracket did not fix it: the
        # bracket ALSO provided this restart.
        lines.append("write T1CON 0x27")

    def inject_step_hold(freq_khz, ms, chunk_ms=5):
        """Advance `ms` of simulated time with the snoop signal held present throughout.

        A single injection before a long step is not enough: the firmware resets TMR1 on every
        10 ms tick, so only the first tick of the step would see the injected count and the rest
        would read an empty gate window, which the classifier reports as its 160m no-signal
        default. Injecting before each `chunk_ms` chunk keeps the measured band stable for the
        whole step, exactly as continuous RF would.
        """
        for _ in range(ms // chunk_ms):
            write_tmr1_count(freq_khz)
            lines.append(stepi(chunk_ms))
        sample()

    def band_preflight(all_bands=False):
        # With `--bands`, BAND_TESTS already IS the narrowed list, so this needs no special case.
        band_tests = BAND_TESTS if all_bands else [("40m", 7000, 3)]
        for band_name, freq_khz, expected_band in band_tests:
            lines.append(f"# BAND PREFLIGHT: {band_name} @ {freq_khz} kHz (expected {expected_band})")
            if all_bands:
                # FREQ_CTR only. Inject then step a FULL 10 ms gate per iteration: the firmware
                # reads-and-zeroes TMR1 on every freq_counter_tick_10ms(), so each gate then reads a
                # stable count and the classifier reaches STABILITY_REQUIRED_TICKS=2. With 5 ms
                # steps the injection raced the gate and the frequency flickered (1800 -> 16 ->
                # 3600), leaving current_band unsettled - the "TX lock failed ... freq=0, band=1"
                # bug. This branch is FREQ_CTR-only because the preflight feeds every scenario's
                # timeline; changing the shared cadence broke the base PTT release.
                for _ in range(4):
                    write_tmr1_count(freq_khz)
                    lines.append(stepi(10))
                    sample()
            else:
                # Every other scenario: unchanged cadence (8 x 5 ms). 5 ms, not 10 ms, because a
                # 10 ms sample interval aliases with the firmware's 10 ms TMR1 reset, so at 5 ms
                # every tick window contains at least one post-tick sample.
                for _ in range(8):
                    write_tmr1_count(freq_khz)
                    lines.append(stepi(5))
                    sample()
        lines.append("# Restore 40m before scenario PTT stimulus")
        for _ in range(8):
            write_tmr1_count(7000)
            lines.append(stepi(5))
            sample()

    if trip_name == "SWR1_1P5":
        lines[3:5] = ["write pin RA0 5.000v", "write pin RA1 0.200v"]
    if trip_name == "FREQ_CTR":
        # --- Finish startup inhibit period (1050ms) ---
        for _ in range(105):
            lines.append(stepi(10))
            sample()

        band_preflight(all_bands=True)
        for band_name, freq_khz, expected_band in BAND_TESTS:
            lines.append(f"# TX BAND CHECK: {band_name} @ {freq_khz} kHz (keyed at this band only)")
            # Re-inject every 5 ms and step 5 ms, holding ONE frequency for the whole phase.
            # Two properties come from this and both are required:
            #   * 5 ms chunks: the firmware zeroes TMR1 on each 10 ms tick, so injecting once per
            #     chunk keeps a fresh count in the register whatever the tick/step phase is. A
            #     10 ms step assumed the injection landed inside the gate and drifted out of phase
            #     later in the run (FREQ_CTR failed at 20m in the suite while passing in isolation).
            #   * one constant frequency per phase: the classifier needs STABILITY_REQUIRED_TICKS=2
            #     consecutive gates on the same band, and a frequency that never changes while
            #     keyed cannot move a relay under the keyed amplifier (the I5 hot switch).
            def hold_band(freq_khz, chunks):
                # Re-inject once per simulated MILLISECOND, inside the step (see
                # INJECTIONS_PER_CHUNK). Same number of MDB writes and the same phase length as
                # injecting them in one burst - only their position inside the step changed, and that
                # is what puts a fresh count within a millisecond of every 10 ms gate.
                for _ in range(chunks):
                    for _repeat in range(INJECTIONS_PER_CHUNK):
                        write_tmr1_count(freq_khz)
                        lines.append(stepi(1))
                    sample()

            # --- Phase A: establish the band while UNKEYED (all relay movement happens here) ---
            hold_band(freq_khz, 60)           # 300 ms
            # --- Phase B: key, frequency unchanged; engage to stage 3 and lock ---
            # 400 ms, not 600: enough for the three 20 ms stages AND for the unkeyable interlock
            # (LOCK_LOSS_UNKEYABLE_MS = 200 ms) to fire when the measurement is not there, and no more
            # - everything after the flag is aftermath the operator does not want traced.
            lines.append("write pin RC0 0v")
            hold_band(freq_khz, 80)
            # --- Phase C: release first, still the same frequency ---
            lines.append("write pin RC0 5v")
            hold_band(freq_khz, 40)           # 200 ms

        lines.append("quit")
        return "\n".join(lines)

    if trip_name == "FREQ_CTR_FAIL":
        # The key-down must land well clear of the startup inhibit or the firmware ignores
        # PTT entirely (state 5 STARTUP INHIBIT) and the latch assertion sees nothing keyed.
        # Measured 2026-09-24: at 105 x 10 ms the keyed window (1.05-1.25 s of harness time)
        # ended just as the inhibit cleared at ~1.25 s, so every keyed sample was still
        # inhibited. Wait 1.30 s and hold the key for 400 ms; there is no snoop timeout in
        # the firmware, so a longer key-down cannot unlatch PTT.
        for _ in range(130):
            lines.append(stepi(10))
            sample()
        lines.append("# No Timer1 writes: simulate a missing frequency-counter signal")
        lines.append("write pin RC0 0v")
        for _ in range(40):
            lines.append(stepi(10))
            sample()
        lines.append("write pin RC0 5v")
        for _ in range(5):
            lines.append(stepi(10))
            sample()
        lines.append("quit")
        return "\n".join(lines)

    if trip_name == "SELF_TEST_DIAG":
        # The firmware-only diagnostic (docs/firmware-self-test-diagnostic.md): boot far enough for
        # the main loop to be established (the LCD/ADC init __delay_ms loops are slow in the model),
        # then set g_diag_request. The diagnostic may run while the startup inhibit is still active
        # (a valid cold/bypass state - see diag_selftest_request), so we do not need to wait out the
        # whole inhibit, just enough for the main loop. The firmware runs every check itself and
        # reports PASS/FAIL in g_diag_result; the harness only reads the verdict.
        for _ in range(5):
            lines.append(stepi(210))
            sample()
        lines.append("# Trigger the diagnostic via g_diag_request (written by .sym address)")
        diag_addr = symbol_address("g_diag_request")
        lines.append(f"write /r 0x{diag_addr:03X} 0x01")
        # Output loop (11 outputs x 2 holds) + sequencer walk + LCD + EEPROM, with margin.
        for _ in range(100):
            lines.append(stepi(5))
            sample()
        lines.append("quit")
        return "\n".join(lines)

    if trip_name == "SELF_TEST_DIAG_STUCK":
        # Fault-injection companion to SELF_TEST_DIAG: pin the TX output (RC5) to the wrong level
        # BEFORE triggering, so the diagnostic's own assert-and-verify loop reads it back wrong and
        # must flag DIAG_OUTPUTS. The model reads an output pin from its LAT, so make RC5 an input
        # (TRISC bit 5 set; RC0/RC2 stay inputs) and drive it high: active-low TX then reads
        # "not asserted" while the firmware holds it asserted. The amplifier is cold throughout.
        for _ in range(5):
            lines.append(stepi(210))
            sample()
        lines.append("# Pin TX (RC5) to the wrong level, then trigger the diagnostic")
        lines.append("write TRISC 0x25")
        lines.append("write pin RC5 5v")
        diag_addr = symbol_address("g_diag_request")
        lines.append(f"write /r 0x{diag_addr:03X} 0x01")
        for _ in range(100):
            lines.append(stepi(5))
            sample()
        lines.append("quit")
        return "\n".join(lines)

    if trip_name in SELFTEST_SCENARIOS:
        # The UNHAPPY paths: establish a valid 40m measurement, key on it, then force the failure
        # the scenario is named after. The firmware's own self-test must flag it, open the RF path
        # and name it on the panel (asserted in validate_selftest). The prelude is skipped - the
        # "PTT ignored during startup" check belongs to the base scenario only.
        for _ in range(5):
            lines.append(stepi(210))
            sample()
        band_preflight()      # 40m (7000 kHz) classified, relay on 40m

        # Inject once per simulated millisecond INSIDE each 5 ms step (the hold_band pattern): the
        # firmware zeroes TMR1 on every 10 ms gate, so a count has to be back in the register within
        # a millisecond of every gate for the keyed window to see it (the 80m lock fix, 2026-09-25).
        def hold(freq_khz, chunks):
            for _ in range(chunks):
                for _repeat in range(INJECTIONS_PER_CHUNK):
                    write_tmr1_count(freq_khz)
                    lines.append(stepi(1))
                sample()

        lines.append("# Key on 40m and let the engage reach BIAS-ON and lock")
        lines.append("write pin RC0 0v")
        hold(7000, 60)        # 300 ms

        if trip_name == "SELFTEST_BAD_BAND":
            # The counter degrades while keyed: pulses keep arriving but the frequency falls below
            # the classifier's 1000 kHz floor (500 kHz here). raw>0 and freq<1000 -> BAD_BAND.
            hold(500, 80)     # 400 ms out-of-spec while keyed
        elif trip_name == "SELFTEST_TX_SENSE":
            # A T/R driver that never came up: the model reads an output pin from its LAT, so make
            # RC5 an input first (TRISC bit 5 set; the rest of the port untouched) and drive it high.
            # SENSE_TX then reads not-asserted while the firmware holds it asserted -> TX_SENSE.
            lines.append("write TRISC 0x25")
            lines.append("write pin RC5 5v")
            hold(7000, 80)    # 400 ms
        else:  # SELFTEST_REL_STUCK
            # A bias driver that sticks asserted after unkey: make RC7 an input (TRISC bit 7 set) and
            # hold it low, then release. The firmware commands the bias off, but the pin stays
            # asserted -> the idle output check raises REL_STUCK.
            lines.append("write TRISC 0x85")
            lines.append("write pin RC7 0v")
            lines.append("write pin RC0 5v")
            for _ in range(80):
                lines.append(stepi(5))
                sample()
        lines.append("write pin RC0 5v")
        for _ in range(10):
            lines.append(stepi(10))
            sample()
        lines.append("quit")
        return "\n".join(lines)

    if not temperature_trip:
        # --- Briefly assert PTT during startup; it must have no effect while inhibited ---
        lines.append("write pin RC0 0v")
        for _ in range(5):  # 50 ms while startup inhibit is active
            lines.append(stepi(10))
            sample()
        lines.append("write pin RC0 5v")

    # --- Finish the settle (startup inhibit) period: 1100ms total ---
    # Stepped in a few big blocks instead of 105 ten-millisecond samples. Nothing inside this stretch
    # is asserted - the "PTT is ignored during startup inhibit" check reads the prelude ABOVE - and
    # every sample costs one MDB command per printed item, for which the model charges simulated time.
    # MEASURED 2026-09-25 as one of the two biggest avoidable costs in the suite (105 samples = ~4700
    # MDB commands per scenario, 11 scenarios).
    for _ in range(5):
        lines.append(stepi(210 if not temperature_trip else 220))
        sample()
    band_preflight()
    # --- Assert PTT (pull RC0 low), triggering SETTLE high for 10 ms ---
    # The radio transmits once PTT is asserted, so keep the 40m snoop signal present for the
    # whole keyed window. Without this the injected measurement goes stale (the 10 ms tick
    # resets TMR1, so the next tick reads zero counts) and the firmware correctly refuses to
    # leave bypass: "RF present while receiving, silent while transmitting" is the opposite of
    # a real transmission. See docs/first-dit-band-detection.md.
    lines.append("write pin RC0 0v")
    # Fine-grained steps to catch SETTLE high pulse (comparator reset)
    for _ in range(12):  # ~12 ms sampled every 1 ms
        write_tmr1_count(7000)
        lines.append(stepi(1))
        sample()
    # Continue simulation for sequencer actions (TX, TX_VCC, etc), 200 ms more
    for _ in range(10 if temperature_trip else 40):
        write_tmr1_count(7000)
        lines.append(stepi(5))
        sample()
    # Hold PTT low for 500 ms before releasing it.
    for _ in range(100):
        write_tmr1_count(7000)
        lines.append(stepi(5))
        sample()

    if trip_name == "SWR1_1P5":
        lines.append("write pin RA0 5.000v")
        lines.append("write pin RA1 0.200v")
        for _ in range(20):  # prove 1.5:1 remains in TX for another 100ms
            lines.append(stepi(5))
            sample()
        lines.append("quit")
        return "\n".join(lines)
    if trip_name and not temperature_trip:
        if trip_name == "CURRENT":
            # Ramp the current-sense voltage up so the firmware's raw value crosses its 40 A
            # threshold with clean margin, then HOLD it there so the trip is definitely observed.
            #
            # Zero current is 2.5 V (CURRENT_SENSOR_ZERO_RAW = 512 on the 10-bit scale the ADC
            # now produces after the Q10 >>2 fix). Each amp is (2.5 V) * (511 counts) / 70 A of
            # scale, so 40 A sits at 2.5 + 40/70*2.5 = 3.929 V. The old ramp stopped at 3.964 V -
            # barely 1% over the threshold - and broke out before sampling, so the trip was a
            # coin-flip. Drive to a voltage well past the trip point and step through it.
            for amp in (20.0, 30.0, 40.0, 50.0, 60.0):
                voltage = 2.5 + (amp / 70.0) * 2.5
                lines.append(f"write pin RB1 {voltage:.3f}v")
                lines.append(stepi(20))  # settle at this level
                sample()
            lines.append(f"write pin RB1 {2.5 + (60.0 / 70.0) * 2.5:.3f}v")  # hold past threshold
            for _ in range(20):  # 20 ms well over threshold: the trip is unambiguous
                lines.append(stepi(1))
                sample()
            lines.append("write pin RB1 0.000v")  # sensor output falls when TX is removed
            for _ in range(10):
                lines.append(stepi(5))
                sample()
            safe_inputs = {"CURRENT": [("RB1", 2.857)]}  # 10A maximum on the next PTT attempt
        else:
            safe_inputs = None
        trip_inputs = {
            "SWR1": [("RA0", 2.500), ("RA1", 0.750)],
            "SWR2": [("RA2", 2.500), ("RA3", 0.400)],
            "HWFAULT": [("RB4", 5.000)],
            "CURRENT": [("RB1", 5.000)],
            "OVERDRIVE": [("RB2", 5.000)],
            "DRAIN": [("RB3", 5.000)],
        }
        if trip_name != "CURRENT":
            for pin, voltage in trip_inputs[trip_name]:
                lines.append(f"write pin {pin} {voltage:.3f}v")
            for _ in range(40):
                lines.append(stepi(1))
                sample()
            for _ in range(10):  # show the latched trip state for another 50ms
                lines.append(stepi(5))
                sample()
        if safe_inputs is None:
            safe_inputs = {
            "SWR1": [("RA0", 0.0), ("RA1", 0.0)],
            "SWR2": [("RA2", 0.0), ("RA3", 0.0)],
            "HWFAULT": [("RB4", 0.0)], "CURRENT": [("RB1", 0.0)],
            "OVERDRIVE": [("RB2", 0.0)], "DRAIN": [("RB3", 0.0)]
            }
        for pin, voltage in safe_inputs[trip_name]:
            lines.append(f"write pin {pin} {voltage:.3f}v")
        lines.append("write pin RC0 5v")
        # The release must be held LONGER than the firmware's PTT poll latency, or the release
        # edge is never seen: the firmware then never re-arms, `handle_ptt_transition(true)` is
        # never called, the latch is never cleared, and the scenario fails with "did not clear
        # and re-enter TX" even though the fault condition had already gone away. MEASURED
        # 2026-09-25 with repro_swr1_rearm.py: the poll takes **54.0 ms** of harness time at this
        # point in the run, against the 50 ms this window used to give it - so the SWR1 scenario
        # failed on Windows, and the failure moved with any change that shifted the phase (the
        # cause is the main-loop pass length, not the trip: the LCD refresh runs `__delay_ms`
        # loops compiled for the real 64 MHz core against a model ~8x slower). 200 ms gives the
        # poll ~4x the measured latency and matches the base scenario's own release window.
        for _ in range(200):
            write_tmr1_count(7000)
            lines.append(stepi(1))
            sample(release=True)
        lines.append("write pin RC0 0v")
        # Re-arm: the trip must clear and the TX sequence must run back to stage 3 with every TX
        # output active-low. That is the 10 ms comparator-reset pulse, the band re-establish
        # (bypass-snoop decode of the 7000 kHz injection plus relay settle), then three 20 ms
        # sequencer stages (0 -> 1 -> 2 -> 3) and the 5 ms trip shutdown unwind. The old 120 ms
        # window was too short: it only reached stage 1 (band just established) before the harness
        # stopped stepping, which read as "did not clear and re-enter TX" even though the fault had
        # already cleared. 400 ms covers decode + settle + 3 stages with margin. The re-entry it is
        # proving is the STEADY SEQ_BIAS_ON (BIAS-ON) state, which lasts far longer than any sampling
        # interval, so it is sampled every 2 ms, not 1 ms: halving the samples of this window is one of
        # the biggest single wins in the suite (8 trip scenarios x 400 samples x ~45 MDB commands), and
        # nothing here can be missed at 2 ms.
        for _ in range(200):
            write_tmr1_count(7000)
            lines.append(stepi(2))
            sample()
        lines.append("quit")
        return "\n".join(lines)
    if temperature_trip:
        # The operator keeps the key down through the whole thermal cycle, so the radio is
        # transmitting throughout: keep the 40m snoop signal present so the amplifier can
        # re-establish the band after the trip clears (it must never key on the classifier's
        # no-signal default - see docs/first-dit-band-detection.md).
        # Raise the temperature stimulus from 2.5V to 5V over one simulated second.
        for step in range(1, 21):
            voltage = 2.5 + step * 0.125
            lines.append(f"write pin RA5 {voltage:.3f}v")
            if step < 20:
                inject_step_hold(7000, 50)  # 50ms per ramp step, signal held present
            else:
                for _ in range(10):  # capture the five-millisecond shutdown sequence
                    write_tmr1_count(7000)
                    lines.append(stepi(1))
                    sample()
        for _ in range(10):  # show the latched trip state for another 500ms
            inject_step_hold(7000, 50)
        # Lower the temperature stimulus back to 2.5V over two simulated seconds.
        for step in range(19, -1, -1):
            voltage = 2.5 + step * 0.125
            lines.append(f"write pin RA5 {voltage:.3f}v")
            inject_step_hold(7000, 50)  # recovery ramp; the radio is still transmitting
        lines.append("quit")
        return "\n".join(lines)
    # --- Release PTT (RC0 back high): relays open, then VCC, then bias ---
    # Sampled every 1 ms with the LEAN release sample set: the unwind is 20 ms per stage and the
    # firmware can collapse a stage into one main-loop pass, so the ordered release is only provable
    # at this resolution (see RELEASE_SAMPLE_VARS and validate_sequence).
    lines.append("write pin RC0 5v")
    for _ in range(200):  # 1 ms steps, 200 ms of unkey
        lines.append(stepi(1))
        sample(release=True)
    lines.append("quit")
    return "\n".join(lines)

# Benign, expected MDB noise. The simulator has no clock-source mux for TMR1/TMR3/TMR5,
# and this firmware never configures those timers, so the warning fires on every reset and
# means nothing here (see the build-test skill). `W9602-COMP` is the same kind of message for the
# COMPARATOR peripheral: "DAC Voltage Source Peripheral not yet implemented to act as input to
# Comparator" - the on-chip DAC cannot be routed into a comparator in the model, and this design
# does not use either: the comparators that combine into INPUT_HARD_FAULT are EXTERNAL hardware, and
# the firmware touches no CMxCON/DAC register at all (it only drives the latch-reset line). Both
# fire once per `program`/reset, so they are stripped from everything the harness shows or logs -
# they otherwise bury the progress lines and turn up in the stderr tail of an unrelated failure.
# run_sim.sh/.ps1 have filtered the same tokens for exactly this reason.
#
# Stripping is display-only: these lines match no parser pattern, so removing them cannot
# change a pin/variable reading. A chunk boundary could in principle split a token, which
# would leave a harmless partial line - it can never corrupt a value the parser accepts.
MDB_NOISE_TOKENS = ("W0106-SIM", "W9602-COMP", "W0223-ADC")


def strip_mdb_noise(text: str) -> str:
    """Drop lines containing a benign MDB noise token, leaving everything else verbatim."""
    if not any(token in text for token in MDB_NOISE_TOKENS):
        return text
    return "".join(
        line
        for line in text.splitlines(keepends=True)
        if not any(token in line for token in MDB_NOISE_TOKENS)
    )


def run_mdb(mdb_path: Path, script: str, timeout: float = 1500) -> str:
    """Run one mdb session to completion and return its combined output.

    `timeout` is a last-resort net, not the budget: `run_suite_with_watchdog.py` owns the
    real budget and kills the whole tree when it expires, so this has to sit *above* the
    launcher's `--timeout` for the launcher to win the race and report a clean
    `TIMEOUT ... END code=` line instead of the child dying first.

    The value is sized for the slowest supported host, because MDB's speed is a property
    of its JVM plus the simulator, not of this repo: measured 2026-09-22, the merged suite
    takes 356 s on Windows 10 against ~150 s on macOS and the first-dit proof ~55 s
    against ~20 s (2.4x), so the old 280 s default killed healthy Windows runs mid-flight.
    Do not shrink this back to a macOS-sized number.
    """
    with tempfile.NamedTemporaryFile("w", suffix=".mdb", delete=False) as f:
        f.write(script)
        script_path = f.name
    try:
        # stdin=DEVNULL + platform_process.isolated_spawn_kwargs() detach mdb from our
        # controlling tty so a killed/hung mdb/JVM can never leave the terminal in raw
        # mode (see bugfixes.md). That is start_new_session on POSIX; on Windows, where
        # the argument is ignored, it is CREATE_NEW_PROCESS_GROUP instead.
        proc = subprocess.Popen(
            [str(mdb_path), script_path], stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True,
            **procutil.isolated_spawn_kwargs(),
        )
        debug_path = os.environ.get("PICAMP_MDB_DEBUG_LOG")
        if debug_path:
            debug_file = open(debug_path, "a", buffering=1)
            debug_lock = threading.Lock()
            captured = {"stdout": [], "stderr": []}
            byte_counts = {"stdout": 0, "stderr": 0}
            # Partial lines carried between reads. A pipe read of 4096 bytes splits MDB output
            # wherever it happens to land, so writing each chunk straight through put half-lines
            # in the log - the reader watching it saw `ault_latched` rather than
            # `g_fault_latched` and reasonably called it strange output (user report, 2026-09-22).
            # Nothing is written until a full line is available; the tail of a read is held here.
            partial = {"stdout": "", "stderr": ""}

            def drain_stream(stream_name, stream):
                for chunk in iter(lambda: stream.read(4096), ""):
                    # Filtered here, at the single capture point, so the transcript the parser
                    # sees, the live debug log, the heartbeat byte counts and the stderr tail
                    # printed on failure are all free of the benign reset warning.
                    chunk = strip_mdb_noise(chunk)
                    if not chunk:
                        continue
                    captured[stream_name].append(chunk)
                    byte_counts[stream_name] += len(chunk.encode(errors="replace"))
                    # Raw text, deliberately NOT a repr: `{chunk!r}` turns every newline into a
                    # literal "\n" and every tab into "\t", and MDB's pin dumps are
                    # tab-separated tables, so escaping renders the log unreadable for the
                    # human watching the run (user feedback, 2026-09-22).
                    #
                    # One `os`-level write per complete line (for stderr, a line at a time) so
                    # a reader tailing this file always sees whole records.
                    buffered = partial[stream_name] + chunk
                    sep = "\n" if stream_name == "stdout" else "\r\n"
                    if sep in buffered:
                        head, _, partial[stream_name] = buffered.rpartition(sep)
                        with debug_lock:
                            debug_file.write(head + sep)
                    else:
                        partial[stream_name] = buffered[:8192]

            debug_file.write(
                f"[{time.strftime('%Y-%m-%dT%H:%M:%S%z')}] MDB_START pid={proc.pid}\n"
            )
            readers = [
                threading.Thread(target=drain_stream, args=("stdout", proc.stdout), daemon=True),
                threading.Thread(target=drain_stream, args=("stderr", proc.stderr), daemon=True),
            ]
            for reader in readers:
                reader.start()
            try:
                proc.wait(timeout=timeout)
            except subprocess.TimeoutExpired:
                procutil.kill_tree(proc.pid)
                proc.wait()
                for reader in readers:
                    reader.join(timeout=2)
                stderr_tail = "".join(captured["stderr"])[-2000:]
                if stderr_tail:
                    debug_file.write(
                        f"[{time.strftime('%Y-%m-%dT%H:%M:%S%z')}] MDB_STDERR_TEXT_BEGIN\n"
                        f"{stderr_tail}\n"
                        f"[{time.strftime('%Y-%m-%dT%H:%M:%S%z')}] MDB_STDERR_TEXT_END\n"
                    )
                debug_file.write(
                    f"[{time.strftime('%Y-%m-%dT%H:%M:%S%z')}] MDB_STDERR_TAIL "
                    f"bytes={byte_counts['stderr']} tail={stderr_tail!r}\n"
                )
                debug_file.write(
                    f"[{time.strftime('%Y-%m-%dT%H:%M:%S%z')}] MDB_TIMEOUT "
                    f"stdout_bytes={byte_counts['stdout']} stderr_bytes={byte_counts['stderr']}\n"
                )
                debug_file.close()
                sys.exit(f"error: mdb timed out after {timeout}s and was killed")
            for reader in readers:
                reader.join(timeout=2)
            stderr_tail = "".join(captured["stderr"])[-2000:]
            if stderr_tail:
                debug_file.write(
                    f"[{time.strftime('%Y-%m-%dT%H:%M:%S%z')}] MDB_STDERR_TEXT_BEGIN\n"
                    f"{stderr_tail}\n"
                    f"[{time.strftime('%Y-%m-%dT%H:%M:%S%z')}] MDB_STDERR_TEXT_END\n"
                )
                debug_file.write(
                    f"[{time.strftime('%Y-%m-%dT%H:%M:%S%z')}] MDB_STDERR_TAIL "
                    f"bytes={byte_counts['stderr']} tail={stderr_tail!r}\n"
                )
            debug_file.write(
                f"[{time.strftime('%Y-%m-%dT%H:%M:%S%z')}] MDB_EXIT "
                f"status={'PASS' if proc.returncode == 0 else 'FAIL'} "
                f"code={proc.returncode} stdout_bytes={byte_counts['stdout']} "
                f"stderr_bytes={byte_counts['stderr']} "
                f"stderr_tail={'logged' if stderr_tail else 'empty'}\n"
            )
            debug_file.close()
            if proc.returncode != 0:
                sys.exit(f"error: mdb exited with code {proc.returncode}; stderr tail: {stderr_tail[-500:]}")
            return "".join(captured["stdout"] + captured["stderr"])
        try:
            stdout, stderr = proc.communicate(timeout=timeout)
        except subprocess.TimeoutExpired:
            procutil.kill_tree(proc.pid)
            proc.communicate()
            sys.exit(f"error: mdb timed out after {timeout}s and was killed")
        return stdout + stderr
    finally:
        Path(script_path).unlink(missing_ok=True)


PRINT_RE = re.compile(r"^(R[A-Z]\d+)\s+\S+\s+(?:(HIGH|LOW)|([\d.]+)V)", re.MULTILINE)
STEPI_RE = re.compile(r"^Stepi\s+(\d+)")
VAR_NAME_RE = re.compile(r"^(g_[\w\.]+)=$")


def block_reason(state: dict) -> str | None:
    """Returns a human-readable reason PTT/TX is blocked, or None if it isn't."""
    if state.get("g_startup_inhibit") == "true":
        return "STARTUP INHIBIT"
    if state.get("g_comparator_reset_active") == "true":
        return "PTT_RESET_PULSE"
    if state.get("g_fault_latched") == "true":
        try:
            reason_bits = int(state.get("g_trip_reason", "0"))
        except ValueError:
            reason_bits = 0
        names = [name for bit, name in TRIP_REASON_BITS if reason_bits & bit]
        return "FAULT: " + "+".join(names) if names else "FAULT: UNKNOWN"
    return None


def validate_frequency_ready(samples, scenario_name="unknown") -> None:
    matches = [
        sample for sample in samples
        if sample[2].get("g_fc_status.frequency_khz") == "7000"
        and sample[2].get("g_fc_status.current_band") == "3"
    ]
    if not matches:
        print(f"FREQ_DEBUG scenario={scenario_name} missing valid 40m precondition", flush=True)
        raise AssertionError(f"{scenario_name}: frequency counter did not establish valid 40m PTT precondition")


def validate_band_coverage(samples, scenario_name="unknown") -> None:
    for band_name, freq_khz, expected_band in BAND_TESTS:
        # Assert the BAND was classified, not that the measured frequency reads exactly the
        # injected kHz. The firmware resets TMR1 on its 10 ms tick, so the sampled frequency
        # drifts a few counts from the injected value (25000 kHz reads 24985/25022) even though
        # the classifier lands on the correct band. Requiring an exact `frequency_khz == 25000`
        # match was why this failed on 10m while the band was in fact correctly classified (6).
        # current_band == expected_band with a non-zero measured frequency is the real property.
        matches = [
            sample for sample in samples
            if sample[2].get("g_fc_status.current_band") == str(expected_band)
            and sample[2].get("g_fc_status.frequency_khz") not in ("", "0", None)
        ]
        if not matches:
            observed_pairs = sorted({
                (sample[2].get("g_fc_status.frequency_khz"),
                 sample[2].get("g_fc_status.current_band"))
                for sample in samples
            })
            observed_frequency = [
                (sample[2].get("g_fc_status.frequency_khz"),
                 sample[2].get("g_fc_status.current_band"),
                 sample[2].get("g_fc_status.band_locked"),
                 sample[2].get("g_ptt_active"),
                 sample[2].get("g_sequence_stage"))
                for sample in samples
                if sample[2].get("g_fc_status.frequency_khz") != ""
            ]
            print(f"FREQ_DEBUG scenario={scenario_name} samples={len(samples)}", flush=True)
            print(f"FREQ_DEBUG missing={band_name}@{freq_khz}kHz expected_band={expected_band}", flush=True)
            print(f"FREQ_DEBUG observed_pairs={observed_pairs}", flush=True)
            print(f"FREQ_DEBUG nonempty_frequency_states={observed_frequency}", flush=True)
            raise AssertionError(
                f"{scenario_name}: {band_name} band was not classified at {freq_khz} kHz"
            )


def validate_band_outputs(samples, scenario_name="FREQ_CTR") -> None:
    """Assert the RD2-RD7 band-select outputs agree with current_band.

    Checks the relay selection itself rather than only the internal current_band
    variable, so a regression in update_band_outputs() is caught.
    """
    checked = 0
    for sample in samples:
        # Before the scheduler runs, PORTD may not have been initialised yet.
        if sample[2].get("g_startup_inhibit") != "false":
            continue
        pins = sample[1]
        if not all(pin in pins for pin in BAND_PINS):
            raise AssertionError(f"{scenario_name}: band-select pins were not sampled")
        high = [pin for pin in BAND_PINS if pins[pin] == 1]
        band = sample[2].get("g_fc_status.current_band")
        if band == str(BAND_OUT_OF_SPEC):
            if high:
                raise AssertionError(
                    f"{scenario_name}: band-select outputs {high} driven while out of spec")
            checked += 1
            continue
        expected_pin = BAND_PIN_FOR.get(int(band)) if band and band.isdigit() else None
        if expected_pin is None:
            raise AssertionError(f"{scenario_name}: unexpected current_band value {band!r}")
        if high != [expected_pin]:
            raise AssertionError(
                f"{scenario_name}: band-select outputs {high} do not match "
                f"current_band={band} (expected exactly {expected_pin})")
        checked += 1
    if checked == 0:
        raise AssertionError(f"{scenario_name}: no samples checked for band-select outputs")


def validate_freq_ctr(samples, scenario_name="FREQ_CTR") -> None:
    """The FIRMWARE'S OWN VERDICT is the contract, for each band under test.

    For every band: either the amplifier verified the band and keyed on it (a keyed stage-3 sample with
    the band locked and `current_band` == expected), or the firmware flagged its undefined/unkeyable
    state and NAMED a reason for it. What is deliberately NOT asserted any more is any KEYED
    `g_fc_status.frequency_khz` reading: the firmware reads and resets TMR1 on every 10 ms gate and
    nothing in this model clocks it, so a keyed window could read a hard 0 while the same band read the
    injected frequency unkeyed (2026-09-25) - a property of the simulator's pacing, not of the firmware
    (user instruction, 2026-09-25). The firmware now says what it thinks of itself; the harness reads
    that verdict instead of re-deriving it from a model artefact.
    """
    validate_band_coverage(samples, scenario_name)
    validate_band_outputs(samples, scenario_name)
    flagged = [sample for sample in samples if sample[2].get("g_selftest_failed") == "true"]
    for band_name, freq_khz, expected_band in BAND_TESTS:
        verified_key = [
            sample for sample in samples
            if sample[2].get("g_ptt_active") == "true"
            and sample[2].get("g_sequence_stage") == "3"
            and sample[2].get("g_fc_status.band_locked") == "true"
            and sample[2].get("g_fc_status.current_band") == str(expected_band)
        ]
        if verified_key:
            continue
        if not flagged:
            # Emit the fold-back state of every sample around this band so the stall point is
            # visible in one shot: remembered band vs live band, whether the verify/settle/snoop
            # flags are held, and how far the sequence got. This is the same diagnostic idea as
            # validate_trip's SWR_DEBUG recovery_trace.
            stale = [
                (sample[2].get("g_band_cache_valid"),
                 sample[2].get("g_band_cache_band"),
                 sample[2].get("g_ptt_active"),
                 sample[2].get("g_fc_status.current_band"),
                 sample[2].get("g_fc_status.frequency_khz"),
                 sample[2].get("g_fc_status.band_locked"),
                 sample[2].get("g_band_established"),
                 sample[2].get("g_snoop_active"),
                 sample[2].get("g_band_settle_active"),
                 sample[2].get("g_band_verify_active"),
                 sample[2].get("g_sequence_stage"))
                for sample in samples
            ]
            print(f"FREQ_DEBUG {band_name} lock_samples={stale}", flush=True)
            raise AssertionError(
                f"{band_name} TX lock failed: no keyed stage-3 sample held "
                f"current_band={expected_band} with the band locked, and the firmware's self-test "
                f"never flagged a reason for refusing to key")
        # The amplifier refused to key on this band and said why. Two things have to hold: the
        # firmware never declares that state without a name (the panel is the only read-out on the
        # bench), and the flag is `LOCK_LOSS_UNKEYABLE_MS` of a HOLDING condition, not one sample.
        reason = selftest_reason_text(flagged[0][2].get("g_selftest_reason"))
        if reason in ("", "OK", "UNKNOWN"):
            raise AssertionError(
                f"{band_name}: the firmware flagged the undefined/unkeyable state without a usable "
                f"reason ({reason!r}) - the panel must always name why it refused to key")
        print(f"{band_name}: no verified key -> the firmware itself flagged the undefined state as "
              f"{reason} ({len(flagged)} samples)")
    print("FREQ_CTR passed: all bands classified, band-select outputs matched, and every band either "
          "verified its lock or was flagged by the firmware's own self-test with a named reason")


def validate_selftest(samples, scenario, expected_names) -> None:
    """An UNHAPPY PATH: the firmware must protect the LDMOS and say why on the panel.

    Three properties, and each is exactly what the operator asked to have tested (2026-09-25: *"we
    need to make sure all scenarios protect the LDMOS"*):

    1. The firmware's own self-test FLAGS the undefined/unkeyable state, and the reason mask carries
       the names this scenario is driving it into (read from the firmware, never invented).
    2. The LCD panel at that moment reads `STATE: UNDEFINED` plus those names - a fault condition
       always displays, and the reason is never blank.
    3. The RF path opens and the LDMOS is de-biased the instant the flag lands: within the aftermath
       samples RELAYS, TX_VCC and TX_BIAS are all inactive and the sequence has left BIAS-ON.
    """
    flagged = [s for s in samples if s[2].get("g_selftest_failed") == "true"]
    if not flagged:
        raise AssertionError(
            f"{scenario}: the firmware's self-test never flagged the undefined/unkeyable state")
    first = flagged[0]
    text = selftest_reason_text(first[2].get("g_selftest_reason"))
    missing = [name for name in expected_names if name not in text]
    if missing:
        raise AssertionError(
            f"{scenario}: panel reason {text!r} is missing {missing}; expected {expected_names}")
    lcd = scope_trace.lcd_screen(first[2])
    if lcd[0] != "FAULT:":
        raise AssertionError(f"{scenario}: LCD line 0 is {lcd[0]!r}, not 'FAULT:'")
    if lcd[1] != text:
        raise AssertionError(f"{scenario}: LCD line 1 {lcd[1]!r} != panel reason {text!r}")
    index = samples.index(first)
    aftermath = samples[index:index + 4]
    # The T/R relay (RC5) and TX_VCC (RC6) must always open. The bias (RC7) must too, EXCEPT in
    # REL_STUCK, where the stuck bias IS the fault being proven - the firmware cannot open a pin a
    # dead driver is holding asserted, and the protection is opening the RF path and latching.
    must_open = ["RC5", "RC6"] if scenario == "SELFTEST_REL_STUCK" else ["RC5", "RC6", "RC7"]
    protected = [s for s in aftermath
                 if all(s[1].get(p) == 1 for p in must_open)
                 and s[2].get("g_sequence_stage") != "3"]
    if not protected:
        outputs = [(s[1].get("RC5"), s[1].get("RC6"), s[1].get("RC7")) for s in aftermath]
        raise AssertionError(
            f"{scenario}: the self-test flagged {text!r} but the TX path did not open - the LDMOS "
            f"was not protected (aftermath outputs {outputs})")
    print(f"{scenario}: firmware flagged {text!r}, panel 'FAULT:' / {text}, "
          f"TX path open within {len(aftermath)} samples")


def validate_diag(samples) -> None:
    """The firmware-only diagnostic: the firmware runs every check and the harness reads the
    verdict mask. The harness must NOT re-derive any pin level - the firmware decided, the harness
    reads the answer.

    The simulator proves the OUTPUTS and SEQUENCER checks (and the LCD pattern write) but NOT the
    EEPROM round-trip: the model does not persist the data-EEPROM write (the WR bit clears but the
    byte read back is unchanged), exactly like it does not model Timer1's external clock. So the
    harness asserts the simulator-provable bits (OUTPUTS|SEQUENCER|LCD = 0x07) are clear and allows
    the EEPROM bit (0x08) to be set in the simulator only - on hardware that check passes.
    """
    running = [s for s in samples if s[2].get("g_diag_running") == "true"]
    if not running:
        raise AssertionError("the diagnostic never started (g_diag_request was not acted on)")
    done = [s for s in samples if s[2].get("g_diag_done") == "true"]
    if not done:
        raise AssertionError("the diagnostic never finished (g_diag_done never set)")
    result = int(done[0][2].get("g_diag_result") or "0")
    provable = result & 0x07   # DIAG_OUTPUTS | DIAG_SEQUENCER | DIAG_LCD
    if provable != 0:
        raise AssertionError(
            f"the diagnostic reported FAIL mask 0x{provable:02X} on the simulator-provable checks "
            f"(full mask 0x{result:02X})")
    # Safety: the diagnostic must end cold - no TX output asserted, no keyed LDMOS.
    for s in done:
        if (s[1]["RC5"], s[1]["RC6"], s[1]["RC7"]) != (1, 1, 1):
            raise AssertionError("the diagnostic finished with a TX output still asserted")
    eeprom_note = "" if not (result & 0x08) else " (EEPROM bit set: hardware-only check, not modelled)"
    print(f"SELF_TEST_DIAG passed: firmware verdict 0x{result:02X}{eeprom_note}, "
          f"outputs/sequencer/LCD green, amplifier cold")


def validate_diag_stuck(samples) -> None:
    """Fault-injection companion to SELF_TEST_DIAG: a TX output pinned to the wrong level must make
    the firmware's own assert-and-verify loop flag DIAG_OUTPUTS. The harness reads g_diag_result and
    asserts the OUTPUTS bit (0x01) is set - it does not re-derive the pin level. The amplifier must
    still end cold (bypass is re-forced when the run finishes)."""
    done = [s for s in samples if s[2].get("g_diag_done") == "true"]
    if not done:
        raise AssertionError("the diagnostic never finished (g_diag_done never set)")
    result = int(done[0][2].get("g_diag_result") or "0")
    if not (result & 0x01):  # DIAG_OUTPUTS
        raise AssertionError(
            f"a pinned-wrong TX output was not flagged: g_diag_result=0x{result:02X} "
            f"(DIAG_OUTPUTS 0x01 expected)")
    for s in done:
        if (s[1]["RC5"], s[1]["RC6"], s[1]["RC7"]) != (1, 1, 1):
            raise AssertionError("the diagnostic finished with a TX output still asserted")
    print(f"SELF_TEST_DIAG_STUCK: firmware verdict 0x{result:02X} (DIAG_OUTPUTS flagged - the "
          f"expected fault), amplifier cold")


# One unhappy-path scenario per self-test reason the model can actually drive the firmware into.
# Deliberately NOT here: a band that changes under the amplifier (BAND_CHG) - a rig cannot QSY in
# 200 ms, so a test that injects an instantaneous band swap is testing the model's pacing, not a
# real hazard (user instruction, 2026-09-25). NO_RF / NO_BAND / NO_LOCK are already covered by
# FREQ_CTR_FAIL.
SELFTEST_SCENARIOS = {
    "SELFTEST_BAD_BAND": ["BAD_BAND"],
    "SELFTEST_TX_SENSE": ["TX_SENSE"],
    "SELFTEST_REL_STUCK": ["REL_STUCK"],
}


def validate_freq_ctr_failure(samples) -> None:
    """No decodable band must not key the amplifier (first-dit bypass snoop).

    Under the old semantics PTT itself was refused; now PTT is latched and the amplifier is
    held in bypass while the radio's first RF burst is snooped for. What must never happen
    is active TX, because the amplifier would then be amplifying through an unverified
    filter. See docs/first-dit-band-detection.md.
    """
    # Prove the stimulus actually drove PTT, otherwise a failed pin write would make
    # the rest of this negative test pass vacuously.
    if not any(sample[1].get("RC0") == 0 for sample in samples):
        raise AssertionError("PTT was never driven low, so bypass-snoop was not exercised")
    validate_band_outputs(samples, "FREQ_CTR_FAIL")
    latched = [sample for sample in samples if sample[2].get("g_ptt_active") == "true"]
    if not latched:
        raise AssertionError("PTT was not latched when the frequency counter had no signal")
    if any(sample[2].get("g_snoop_active") != "true" for sample in latched):
        raise AssertionError("latched PTT did not hold the amplifier in bypass-snoop")
    if any(sample[2].get("g_state") != str(STATE_BYPASS_SNOOP) for sample in latched):
        raise AssertionError("bypass-snoop did not report STATE_BYPASS_SNOOP")
    if any(sample[2].get("g_sequence_stage") != "0" for sample in samples):
        raise AssertionError("frequency-counter failure advanced the TX sequence")
    if any((sample[1]["RC5"], sample[1]["RC6"], sample[1]["RC7"]) != (1, 1, 1)
           for sample in samples):
        raise AssertionError("frequency-counter failure did not keep all TX outputs inactive")
    if any(sample[2].get("g_fc_status.band_locked") == "true" for sample in samples):
        raise AssertionError("the band was locked with no usable snoop measurement")
    print(f"FREQ_CTR_FAIL passed: no decodable band, so {len(latched)} samples held latched "
          "PTT in bypass-snoop with TX/TX_VCC/TX_BIAS inactive, stage 0 and the band unlocked")


def split_scenarios(raw_output: str, expected: int):
    """Split one MDB transcript into one sample-group per suite scenario.

    Each scenario now re-programs the ELF (see the suite builder), and `Program succeeded.` is
    printed EXACTLY once per `program` - so it is the reliable per-scenario boundary. The older
    scheme split on "Resetting SFRs", which MDB prints two or three times per load, so the split
    produced spurious fragments and the empty-group filter silently shifted every index
    (scenarios were validated against each other's samples). Splitting on `Program succeeded.`
    and keeping every part - even an empty one - makes the count check honest.
    """
    parts = raw_output.split("Program succeeded.")
    # parts[0] is the preamble before the first program; parts[1:] are one per scenario.
    groups = [(index, parse_trace(chunk)) for index, chunk in enumerate(parts[1:])]
    if len(groups) != expected:
        raise AssertionError(
            f"suite produced {len(groups)} sample groups, expected {expected} scenarios "
            f"({len(parts) - 1} 'Program succeeded.' markers) - the transcript split is wrong, "
            "so no scenario can be trusted (do NOT relax this count; fix the split)")
    return groups


def validate_sequence(samples) -> None:
    """Fail when startup inhibit or either PTT sequencing direction is wrong."""
    startup_samples = [sample for sample in samples if sample[2]["g_startup_inhibit"] == "true"]
    if not any(sample[1]["RC0"] == 0 and all(sample[1][pin] == 1 for pin in ("RC5", "RC6", "RC7"))
               for sample in startup_samples):
        raise AssertionError("PTT was not ignored during startup inhibit")

    active_samples = [sample for sample in samples
                      if sample[2]["g_ptt_active"] == "true" and sample[2]["g_sequence_stage"] == str(int(SequenceStage.SEQ_BIAS_ON))]
    if not active_samples:
        raise AssertionError(f"PTT active sequence did not reach {SequenceStage.SEQ_BIAS_ON.name} "
                             f"({stage_name(str(int(SequenceStage.SEQ_BIAS_ON)))}) - the amplifier "
                             f"never completed the engage")
    active = active_samples[0][1]
    if (active["RC5"], active["RC6"], active["RC7"]) != (0, 0, 0):
        raise AssertionError("active sequence did not drive RELAYS, TX_VCC, TX_BIAS low")

    # Verify that frequency counter locked the band during the transmitting stage
    band_locked_samples = [sample for sample in active_samples
                           if sample[2].get("g_fc_status.band_locked") == "true"]
    if not band_locked_samples:
        raise AssertionError(
            f"Frequency counter band was not locked during {SequenceStage.SEQ_BIAS_ON.name}"
            f" ({stage_name(str(int(SequenceStage.SEQ_BIAS_ON)))}, transmitting)")

    complete_display = next((sample for sample in samples
                             if sample[2]["g_ptt_complete_display_active"] == "true"), None)
    if complete_display is None or (complete_display[1]["RC5"], complete_display[1]["RC6"], complete_display[1]["RC7"]) != (0, 0, 0):
        raise AssertionError("PTT COMPLETE was displayed before all TX outputs went low")

    release_samples = [sample for sample in samples if sample[2]["g_ptt_active"] == "false"]
    release_done = next((sample for sample in release_samples
                         if sample[2]["g_sequence_stage"] == str(int(SequenceStage.SEQ_IDLE))
                         and sample[1]["RC5"] == 1 and sample[1]["RC6"] == 1
                         and sample[1]["RC7"] == 1), None)
    if release_done is None:
        raise AssertionError(
            f"release did not reach {SequenceStage.SEQ_IDLE.name} with RELAYS, TX_VCC and TX_BIAS "
            f"all inactive")

    # The release STAGES are deliberately NOT asserted by membership any more (2026-09-25). It used
    # to require a sample inside SEQ_RELEASE_RELAYS and inside SEQ_RELEASE_VCC, and that is a
    # statement about the simulator's pacing, not about the firmware: `g_sequence_elapsed_ms`
    # advances once per DRAINED Timer2 tick, and MDB's own `print`/`write` commands advance simulated
    # time, so ticks pile up while the CPU is not executing and a whole 20 ms stage then collapses
    # into one main-loop pass. Measured on the base scenario of the 2026-09-25 suite run: the release
    # went SEQ_BIAS_ON -> SEQ_RELEASE_RELAYS -> SEQ_IDLE between two 5 ms samples, with
    # SEQ_RELEASE_VCC never sampled, and the run failed with `release did not enter stage 5` on an
    # amplifier that had just released correctly. What IS asserted is the part that cannot be
    # aliased: the pins come down monotonically in the documented order, and the sequence ends at
    # SEQ_IDLE with every output inactive (above).
    #
    # Monotonic ordering is the property that matters and cannot be aliased: TX_VCC must never be up
    # while RELAYS is low, and TX_BIAS must never be up unless both others are. If those hold over the
    # whole release, the order was right regardless of sampling phase.
    release_window = [sample for sample in release_samples
                      if sample[2]["g_sequence_stage"] in (
                          str(int(SequenceStage.SEQ_RELEASE_RELAYS)),
                          str(int(SequenceStage.SEQ_RELEASE_VCC)),
                          str(int(SequenceStage.SEQ_IDLE)))]
    for sample in release_window:
        pins = sample[1]
        stage = stage_name(sample[2]["g_sequence_stage"])
        when = f"t={sample[0] * SECONDS_PER_INSTRUCTION:.4f}s, stage {stage}"
        if pins["RC6"] == 1 and pins["RC5"] == 0:
            raise AssertionError(
                f"release raised TX_VCC while RELAYS was still low ({when}) - that is the wrong "
                f"order")
        if pins["RC7"] == 1 and (pins["RC5"] == 0 or pins["RC6"] == 0):
            raise AssertionError(
                f"release raised TX_BIAS before RELAYS and TX_VCC were both up ({when}) - that is "
                f"the wrong order")

    # Verify that frequency counter unlocked after TX sequence completes (stage 0)
    if release_done[2].get("g_fc_status.band_locked") == "true":
        raise AssertionError("Frequency counter band remained locked after TX sequence completed")


def validate_trip(samples, trip_name) -> None:
    expected_reason = f"FAULT: {trip_name}"
    trip = next((sample for sample in samples if block_reason(sample[2]) == expected_reason), None)
    if trip is None:
        raise AssertionError(f"{trip_name} trip was not reported")
    if trip[2]["g_ptt_active"] != "true":
        raise AssertionError(f"{trip_name} trip did not occur while PTT was active")
    if trip_name == "CURRENT" and not trip[3]["RB1"] >= 3.9:
        # The trip must occur only once the current-sense voltage has risen past ~40 A (= 3.93 V
        # on the 10-bit ADC scale). Only a LOWER bound is asserted: the exact value depends on the
        # ramp's hold level, and an upper bound tied to one ramp shape is what broke this test when
        # the ramp was widened to overshoot the threshold with margin.
        raise AssertionError(
            f"current trip occurred at {trip[3]['RB1']:.3f}V, below the ~40A threshold (3.9V)")
    fault_samples = [sample for sample in samples
                     if (block_reason(sample[2]) or "").startswith("FAULT:")]
    if any(sample[2]["g_ptt_complete_display_active"] == "true" for sample in fault_samples):
        raise AssertionError(f"{trip_name} fault display was overwritten by PTT_COMPLETE")
    tx_active = next((sample for sample in samples
                      if sample[2]["g_sequence_stage"] == "3" and
                      (sample[1]["RC5"], sample[1]["RC6"], sample[1]["RC7"]) == (0, 0, 0)), None)
    if tx_active is None:
        raise AssertionError(f"{trip_name} trip did not follow an active TX state")
    active_ms = (trip[0] - tx_active[0]) * SECONDS_PER_INSTRUCTION * 1000
    if active_ms < 500:
        raise AssertionError(f"{trip_name} trip occurred after only {active_ms:.1f}ms of TX")
    print(f"TX active before {trip_name} trip: {active_ms:.1f}ms")
    shutdown_done = next((sample for sample in samples
                          if sample[2]["g_fault_latched"] == "true" and
                          (sample[1]["RC5"], sample[1]["RC6"], sample[1]["RC7"]) == (1, 1, 1) and
                          block_reason(sample[2]) == expected_reason), None)
    if shutdown_done is None or (shutdown_done[1]["RC5"], shutdown_done[1]["RC6"], shutdown_done[1]["RC7"]) != (1, 1, 1):
        raise AssertionError("fault did not raise RELAYS and TX_BIAS after five milliseconds")
    if trip_name == "CURRENT":
        if not any(sample[3]["RB1"] == 0.0 for sample in samples[samples.index(trip) + 1:]):
            raise AssertionError("current sensor did not fall to zero during the trip shutdown")
    if trip_name == "TEMPERATURE":
        post_shutdown = samples[samples.index(shutdown_done):]
        if any((sample[1]["RC5"], sample[1]["RC6"], sample[1]["RC7"]) != (1, 1, 1)
               for sample in post_shutdown if sample[2]["g_fault_latched"] == "true"):
            raise AssertionError("temperature trip outputs did not remain high until recovery")
        recovered = next((sample for sample in samples[samples.index(shutdown_done) + 1:]
                          if sample[2]["g_fault_latched"] == "false" and
                          sample[2]["g_sequence_stage"] == "3"), None)
        if recovered is None or (recovered[1]["RC5"], recovered[1]["RC6"], recovered[1]["RC7"]) != (0, 0, 0):
            raise AssertionError("temperature recovery did not re-enter the active TX sequence")
        print("TEMP RECOVERED: TX sequence resumed after hysteresis")
    elif shutdown_done[2]["g_fault_latched"] != "true":
        raise AssertionError(f"{trip_name} fault unexpectedly recovered")
    else:
        recovered = next((sample for sample in samples[samples.index(shutdown_done) + 1:]
                          if sample[2]["g_fault_latched"] == "false" and
                          sample[2]["g_sequence_stage"] == "3"), None)
        if recovered is None:
            recovery_trace = [
                (sample[2].get("g_ptt_active"),
                 sample[2].get("g_fault_latched"),
                 sample[2].get("g_trip_reason"),
                 sample[2].get("g_sequence_stage"),
                 sample[2].get("g_fc_status.frequency_khz"),
                 sample[2].get("g_fc_status.current_band"),
                 sample[2].get("g_fc_status.band_locked"),
                 (sample[1]["RC5"], sample[1]["RC6"], sample[1]["RC7"]),
                 (sample[3]["RA0"], sample[3]["RA1"]))
                for sample in samples[samples.index(shutdown_done):]
            ]
            print(f"SWR_DEBUG {trip_name} recovery_trace={recovery_trace}", flush=True)
            raise AssertionError(f"{trip_name} did not clear and re-enter TX after a PTT re-arm")
        if trip_name == "CURRENT" and recovered[3]["RB1"] > 2.95:
            raise AssertionError("current re-arm exceeded the 10A limit")
        print(f"{trip_name} cleared by PTT re-arm; TX sequence resumed")
    if trip_name == "TEMPERATURE" and trip[3]["RA5"] < 4.0:
        raise AssertionError("temperature ADC input did not rise above 4V")
    print(f"ADC voltages at {trip_name}: " +
          ", ".join(f"{pin}={trip[3][pin]:.3f}V" for pin in ADC_PINS))
    print(f"TRIP: {trip_name} ({expected_reason})")


def validate_swr1_1p5(samples) -> None:
    if any((block_reason(sample[2]) or "").startswith("FAULT:") for sample in samples):
        raise AssertionError("1.5:1 SWR incorrectly tripped")
    active = [sample for sample in samples
              if sample[2]["g_sequence_stage"] == "3" and
              (sample[1]["RC5"], sample[1]["RC6"], sample[1]["RC7"]) == (0, 0, 0)]
    if not active:
        raise AssertionError("1.5:1 SWR did not remain in active TX")
    active_ms = (samples[-1][0] - active[0][0]) * SECONDS_PER_INSTRUCTION * 1000
    if active_ms < 500:
        raise AssertionError(f"1.5:1 SWR was active for only {active_ms:.1f}ms")
    print(f"SWR1 1.50:1 at 2.000kW PEP: no trip; TX remained active for {active_ms:.1f}ms")


# What each scenario is FOR, in the words a reader needs beside a failing waveform. Without this a
# trace is a puzzle: the reader has to re-derive the expectation from this file's assertions before
# they can tell whether the picture is wrong (user instruction, 2026-09-25: *"You still are not
# summarizing with text at the end of the graph why exactly it 'failed' and what it should have done
# instead (ie what you were testing for)."*).
SCENARIO_CHECKS = {
    None: ("The plain transmit cycle: on key-down the T/R relay closes, then TX_VCC after "
           "tx_vcc_delay_ms, then TX_BIAS after tx_bias_delay_ms; on key-up they come down in the "
           "order relay -> VCC -> bias, ending at SEQ_IDLE, with every TX output confirmed inactive "
           "before the band is released."),
    "TEMPERATURE": ("A temperature trip must latch with the outputs shut down, then clear itself "
                    "once the reading falls below the trip point minus the recovery hysteresis, and "
                    "re-enter TX at SEQ_BIAS_ON on a re-established band."),
    "SWR1": ("An SWR1 trip while transmitting must latch with the output shutdown order, and a PTT "
             "re-arm must clear the latch and run the sequence back up to SEQ_BIAS_ON."),
    "SWR2": ("An SWR2 trip while transmitting must latch, and a PTT re-arm must clear it and "
             "re-enter TX at SEQ_BIAS_ON."),
    "HWFAULT": ("A hardware comparator fault (INPUT_HARD_FAULT) must latch and hold the amplifier "
                "off; a PTT re-arm must NOT clear it while the fault input is still asserted."),
    "CURRENT": ("A current trip at the configured limit must latch, and the re-arm must run back to "
                "stage 3 without exceeding the limit."),
    "OVERDRIVE": ("An overdrive trip must latch and be cleared only by a clean PTT re-arm."),
    "DRAIN": ("A drain-voltage trip must latch and be cleared only by a clean PTT re-arm."),
    "SWR1_1P5": ("1.5:1 at full forward power must NOT trip: an SWR below the configured ratio must "
                 "leave the amplifier transmitting."),
    "FREQ_CTR": ("For each band, with RF injected every 5 ms: the band must classify, the band-select "
                 "output must match current_band, and while the band is LOCKED and keyed the counter "
                 "must keep reporting a NON-ZERO frequency - that reading is the evidence the lock is "
                 "holding against a different signal. It should read 0 only when there is no RF."),
    "FREQ_CTR_FAIL": ("With no RF at all: PTT must latch but the amplifier must stay in bypass - it "
                      "must never key on the classifier's no-signal default, and this negative test "
                      "must not be 'fixed' into a passing trip."),
    "SELFTEST_BAD_BAND": ("The counter going out-of-spec while keyed (raw pulses present but the "
                          "frequency outside the classifier's 1000-32000 kHz floor) must make the "
                          "firmware declare the undefined/unkeyable state, open the RF path and show "
                          "STATE: UNDEFINED / BAD_BAND on the panel."),
    "SELFTEST_TX_SENSE": ("A TX output that does not reach the level its stage commands (a stuck "
                          "driver) must make the firmware declare the undefined/unkeyable state, open "
                          "the RF path and show STATE: UNDEFINED / TX_SENSE on the panel."),
    "SELFTEST_REL_STUCK": ("An unkey whose bias output stays asserted (a stuck driver) must make the "
                           "firmware declare the undefined/unkeyable state, keep the RF path open and "
                           "show STATE: UNDEFINED / REL_STUCK on the panel."),
    "SELF_TEST_DIAG": ("The firmware-only diagnostic: on request the firmware asserts and verifies "
                       "every output via its SENSE_* read-back, walks the sequencer 0->1->2->3->0, "
                       "writes an LCD liveness pattern and round-trips the EEPROM, then reports "
                       "PASS/FAIL in g_diag_result and ends cold. The harness reads the verdict "
                       "mask, never re-derives a pin level."),
    "SELF_TEST_DIAG_STUCK": ("The fault-injection companion to SELF_TEST_DIAG: a TX output pinned to "
                              "the wrong level must make the diagnostic's assert-and-verify loop flag "
                              "DIAG_OUTPUTS in g_diag_result - the diagnostic is EXPECTED to report "
                              "the fault here (that is the pass condition), proving a real defect is "
                              "caught rather than just a healthy board passing."),
}


def _observed_summary(samples, scenario=None) -> str:
    """What the samples actually show, in numbers - the `observed` half of a failure note."""
    if not samples:
        return "no samples were parsed from the transcript"
    keyed = [s for s in samples if s[2].get("g_ptt_active") == "true"]
    stage3 = [s for s in keyed if s[2].get("g_sequence_stage") == "3"]
    latched = [s for s in samples if s[2].get("g_fault_latched") == "true"]
    released = [s for s in samples if s[1].get("RC0") == 1]
    release_seen = [s for s in released if s[2].get("g_ptt_active") == "false"]
    parts = [f"{len(samples)} samples, {len(keyed)} keyed, {len(stage3)} at stage 3 (BIAS-ON), "
             f"{len(latched)} with a latched fault"]
    if released:
        parts.append(f"PTT was released for {len(released)} samples and the firmware acknowledged "
                     f"that in {len(release_seen)} of them")
    if scenario == "FREQ_CTR":
        for band_name, _freq_khz, expected_band in BAND_TESTS:
            locked = [s for s in keyed
                      if s[2].get("g_sequence_stage") == "3"
                      and s[2].get("g_fc_status.band_locked") == "true"
                      and s[2].get("g_fc_status.current_band") == str(expected_band)]
            parts.append(f"{band_name}: a verified keyed band lock in {len(locked)} samples")
    flagged = [s for s in samples if s[2].get("g_selftest_failed") == "true"]
    if flagged:
        parts.append(
            f"the firmware's own self-test flagged the undefined/unkeyable state in {len(flagged)} "
            f"samples, first as {selftest_reason_text(flagged[0][2].get('g_selftest_reason'))} "
            f"at t={flagged[0][0] * SECONDS_PER_INSTRUCTION * 1000:.1f} ms")
    last = samples[-1][2]
    parts.append(f"last sample: stage={last.get('g_sequence_stage')} "
                 f"ptt={last.get('g_ptt_active')} latched={last.get('g_fault_latched')} "
                 f"reason={last.get('g_trip_reason')} band={last.get('g_fc_status.current_band')} "
                 f"freq={last.get('g_fc_status.frequency_khz')}kHz "
                 f"locked={last.get('g_fc_status.band_locked')}")
    return "; ".join(parts)


def _argument_value(name):
    """Value of `--name value` on the command line, or None when the flag is absent."""
    if name not in sys.argv[1:]:
        return None
    index = sys.argv.index(name) + 1
    if index >= len(sys.argv):
        sys.exit(f"error: {name} needs a value")
    return sys.argv[index]


def truncate_at_unkeyable(samples):
    """`samples` cut off right after the first sample that shows the flagged failure.

    The firmware DECLARES the state itself (main.c `g_unkeyable` / `g_selftest_failed`, set once a
    self-test check has held for LOCK_LOSS_UNKEYABLE_MS), and the operator's rule is that the test and
    its trace stop there rather than carrying on through hundreds of milliseconds that can only be the
    aftermath (user instruction, 2026-09-25: *"The test and the scope tracing needs to then stop right
    after the undefined state is flagged."*). A few samples of aftermath are kept so the drop-out is
    visible as a transition, not as the last pixel of the trace.
    """
    for index, sample in enumerate(samples):
        if sample[2].get("g_unkeyable") == "true" or sample[2].get("g_selftest_failed") == "true":
            return samples[:index + 3] if index + 3 < len(samples) else samples
    return samples


def _scenario_label(scenario):
    """The suite's user-facing name for a scenario: `None` (the plain PTT cycle) is `base`."""
    return scenario if scenario is not None else "base"


def validate_scenario(scenario, samples) -> None:
    """Run the checks belonging to one suite scenario.

    One function for every scenario, so the suite and `--only <scenario>` cannot drift apart and a
    scenario's checks are declared in exactly one place.
    """
    global LAST_SCENARIO
    LAST_SCENARIO = scenario
    if scenario is None:
        validate_sequence(samples)
        validate_frequency_ready(samples, None)
        return
    if scenario == "FREQ_CTR_FAIL":
        validate_freq_ctr_failure(samples)
        return
    if scenario in SELFTEST_SCENARIOS:
        validate_selftest(samples, scenario, SELFTEST_SCENARIOS[scenario])
        return
    if scenario == "SELF_TEST_DIAG":
        validate_diag(samples)
        return
    if scenario == "SELF_TEST_DIAG_STUCK":
        validate_diag_stuck(samples)
        return
    validate_frequency_ready(samples, scenario)
    if scenario == "SWR1_1P5":
        validate_swr1_1p5(samples)
    elif scenario == "FREQ_CTR":
        validate_freq_ctr(samples, scenario)
    else:
        validate_trip(samples, scenario)


def _failure_context(samples, scenario, exc) -> dict:
    """`check` / `observed` / `why` for a failed scenario's scope trace."""
    return {
        "check": SCENARIO_CHECKS.get(scenario, SCENARIO_CHECKS[None]),
        "observed": _observed_summary(samples, scenario),
        "why": str(exc),
    }


def _describe_scenario_pass(scenario, samples) -> None:
    """Append, for a PASSING scenario, the same prose a failure trace carries: what the test is for
    (SCENARIO_CHECKS) and what the firmware actually did (_observed_summary). A passing run must say
    what it proved, not just "no failure text to report" (user instruction, 2026-09-26)."""
    label = _scenario_label(scenario)
    check = SCENARIO_CHECKS.get(scenario, SCENARIO_CHECKS[None])
    observed = _observed_summary(samples, scenario)
    print(f"PASS {label}: {check}", flush=True)
    print(f"  observed: {observed}", flush=True)


def _scope_events(samples, scenario=None):
    """`(time_ms, label)` for the moments a failure trace should be read against.

    A scope trace without them is a picture of a long run; with them, the reader can see where the
    trip was raised, where PTT was released and where it was re-armed - the three instants every
    re-arm failure is about.
    """
    events = []
    ms = SECONDS_PER_INSTRUCTION * 1000
    # Where the firmware gave up and declared the state undefined/unkeyable (main.c `g_unkeyable`),
    # named with the self-test's own reason rather than the raw mask. The operator's rule is that the
    # test and its trace STOP here, so this is the last instant the trace should be read (user
    # instruction, 2026-09-25).
    unkeyable = next((s for s in samples if s[2].get("g_unkeyable") == "true"), None)
    if unkeyable is not None:
        events.append((unkeyable[0] * ms,
                       f"UNDEFINED: {selftest_reason_text(unkeyable[2].get('g_selftest_reason'))}"))
    trip = next((s for s in samples
                 if s[2].get("g_fault_latched") == "true"
                 and (scenario is None or block_reason(s[2]) == f"FAULT: {scenario}")), None)
    if trip is not None:
        events.append((trip[0] * ms, f"{scenario or 'fault'} trip"))
        after = samples[samples.index(trip):]
        released = next((s for s in after if s[1].get("RC0") == 1
                         and s[2].get("g_ptt_active") == "false"), None)
        if released is not None:
            events.append((released[0] * ms, "PTT released"))
            rekey = next((s for s in samples[samples.index(released):]
                          if s[1].get("RC0") == 0 and s[2].get("g_ptt_active") == "true"), None)
            if rekey is not None:
                events.append((rekey[0] * ms, "PTT re-arm"))
    return events


def parse_trace(output: str):
    """Walks the mdb transcript in order, tracking cumulative instruction count and
    each pin's/variable's most-recently-printed value, sampling a full snapshot every
    time all pins and state variables have been reprinted (i.e. once per Stepi block)."""
    # Fail fast on a STATE_VARS entry the transcript grammar cannot recognise. VAR_NAME_RE only
    # accepts `g_`-prefixed names, so anything else (a register such as PORTC, a non-prefixed
    # global) never sets `awaiting_var`, never lands in state_pending, and therefore means NO
    # sample is ever emitted - the run dies later as "no samples parsed from mdb output", which
    # points at the harness rather than at the one line that was wrong. That cost a run on
    # 2026-09-24, when PORTC/TRISC were added to STATE_VARS to read the PTT pin.
    strays = [name for name in STATE_VARS if not VAR_NAME_RE.match(f"{name}=")]
    if strays:
        raise RuntimeError(
            "parse_trace: STATE_VARS entries the transcript grammar cannot read: "
            + ", ".join(strays)
            + " - VAR_NAME_RE only matches `g_`-prefixed names, so no sample would ever be "
              "emitted. Expose the value through a `g_`-named firmware global instead.")
    samples = []
    instr_count = 0
    pending = {}
    pending_adc = {}
    pending_voltages = {}
    state_pending = {}
    awaiting_var = None

    def emit():
        """Take the accumulated prints as one sample and start the next one empty.

        Two shapes are emitted. A FULL sample carries every pin (PINS + ADC_PINS) and every
        STATE_VARS entry; a LEAN one - the unkey window, see RELEASE_SAMPLE_VARS - carries PINS and
        just the state vars it needs. Both are complete in the sense that matters: nothing that
        belongs to the sample is still arriving.
        """
        samples.append((instr_count, dict(pending), dict(state_pending), dict(pending_voltages)))
        pending.clear()
        pending_adc.clear()
        pending_voltages.clear()
        state_pending.clear()

    for raw_line in output.splitlines():
        line = raw_line.strip()
        m_stepi = STEPI_RE.match(line)
        if m_stepi:
            instr_count += int(m_stepi.group(1))
            continue
        if awaiting_var is not None:
            if line:
                state_pending[awaiting_var] = line
                awaiting_var = None
            continue
        m_var = VAR_NAME_RE.match(line)
        if m_var:
            awaiting_var = m_var.group(1)
            continue
        m = PRINT_RE.match(line)
        if m:
            pin, level, volts = m.groups()
            # A pin block always begins at PINS[0], so seeing it again means the previous block's
            # prints are all in and its state block has ended - that is the boundary a LEAN sample
            # needs, because it never reaches the full STATE_VARS count.
            if pin == PINS[0] and pending and state_pending:
                emit()
            pending[pin] = 1 if level == "HIGH" or (volts is not None and float(volts) >= 2.5) else 0
            if pin in ADC_PINS:
                pending_adc[pin] = 1
                pending_voltages[pin] = float(volts) if volts is not None else (5.0 if level == "HIGH" else 0.0)
        if (len(pending) >= len(PINS) and len(state_pending) == len(STATE_VARS)):
            emit()
    # A lean block at the very end of the transcript is closed by the end of input, not by the next
    # block's first pin print.
    if pending and state_pending and len(pending) >= len(PINS):
        emit()
    LAST_SAMPLES.clear()
    LAST_SAMPLES.extend(samples)
    return samples


# What the last parse/validation looked at, so an unexpected exception can still write a failure text
# that names the scenario and says what the firmware was doing when the harness fell over.
LAST_SCENARIO = None
LAST_SAMPLES = []


def write_crash_report(exc: BaseException) -> Path:
    """Write the prose failure text for a run that CRASHED, not one that failed an assertion.

    Two separate holes showed up on 2026-09-25, both reported by the operator: an uncaught harness
    exception (`KeyError: 'RA0'` out of the trace CSV writer) produced NO failure text at all, so the
    run ended with `TEST_END code=1` and nothing that explained it; and the failure text is exactly
    what the launcher appends to the END of the log (and what the scope trace mirrors), so without a
    file there was no failure text to append either. So anything that raises now leaves a text with
    the same three prose blocks as a real failure, plus the traceback.
    """
    graphs = REPO_ROOT / "_build" / "My_Pic_Project" / "sim" / "graphs"
    try:
        graphs.mkdir(parents=True, exist_ok=True)
    except OSError:
        return graphs / "crash_failure.txt"
    path = graphs / f"{_scenario_label(LAST_SCENARIO).lower()}_failure.txt"
    check = SCENARIO_CHECKS.get(LAST_SCENARIO, SCENARIO_CHECKS[None])
    observed = (_observed_summary(LAST_SAMPLES, LAST_SCENARIO) if LAST_SAMPLES
                else "no samples were parsed before the crash")
    text = (f"FAILED: {_scenario_label(LAST_SCENARIO)} - THE TEST HARNESS ITSELF RAISED\n\n"
            f"WHAT THIS TEST IS FOR\n{check}\n\n"
            f"WHAT THE FIRMWARE ACTUALLY DID\n{observed}\n\n"
            f"WHY THAT IS A FAILURE\nThe harness raised {type(exc).__name__}: {exc}\n"
            f"It stopped before its assertions completed, so this is a defect in the TEST until it is\n"
            f"shown to be a firmware fault.\n\n"
            f"TRACEBACK\n{traceback.format_exc()}")
    try:
        path.write_text(text, encoding="utf-8")
    except OSError:
        pass
    print(text, flush=True)
    return path


def stage_name(value) -> str:
    """`<number> <NAME>` for a `g_sequence_stage` reading - the number AND the name, both.

    The number is what the firmware enum and the assertions use, the name is what makes it
    readable; a trace that shows only one of them is either unreadable or unmatchable (user,
    2026-09-25: *"I want to see its number (4) but also the name"*). Mirrors `sequence_stage_t`
    and `sequence_stage_name()` in firmware/src/main.c - keep in step with those (see the stage
    table in the build-test skill).
    """
    try:
        index = int(str(value).strip())
    except (TypeError, ValueError):
        return f"?({value})"
    return f"{index} {SEQ_STAGE_NAMES.get(index, '?')}"


def write_trace_csv(samples, trace_name, csv_dir):
    """The CSV half of a trace. A LEAN (unkey) sample has no ADC prints and no full state block, so
    its ADC columns are left EMPTY and its state lookups go through `.get` - a bare index here crashed
    the run with `KeyError: 'RA0'` the first time lean release samples existed (2026-09-25)."""
    csv_path = csv_dir / f"{trace_name}.csv"
    with open(csv_path, "w") as f:
        f.write("time_s," + ",".join(PIN_LABELS[p] for p in PINS) +
                "," + ",".join(f"ADC_{pin}_V" for pin in ADC_PINS) +
                ",g_ptt_active,g_sequence_stage,stage_name,g_state,block_reason\n")
        for instr_count, vals, state, adc_voltages in samples:
            t = instr_count * SECONDS_PER_INSTRUCTION
            reason = block_reason(state) or ""
            stage = state.get('g_sequence_stage', "")
            f.write(f"{t:.6f}," + ",".join(str(vals.get(pin, "")) for pin in PINS) +
                    "," + ",".join(f"{adc_voltages[pin]:.3f}" if pin in adc_voltages else ""
                                   for pin in ADC_PINS) +
                    f",{state.get('g_ptt_active', '')},{stage},{stage_name(stage)},"
                    f"{state.get('g_state', '')},{reason}\n")
    return csv_path


def assign_event_label_lanes(events, x_min, x_max):
    lanes = []
    placed = []
    span = max(1.0, x_max - x_min)
    for event_time, event_label, color in sorted(events, key=lambda event: event[0]):
        text = f"{event_label} @ {event_time:.1f} ms"
        half_width = max(span * 0.035, len(text) * span / 180.0)
        start = event_time - half_width
        end = event_time + half_width
        for lane_index, lane_end in enumerate(lanes):
            if start > lane_end:
                lanes[lane_index] = end
                break
        else:
            lane_index = len(lanes)
            lanes.append(end)
        placed.append((event_time, text, color, lane_index))
    return placed, len(lanes)


def draw_event_labels_after_layout(fig, axes, events, x_min, x_max):
    placed, lane_count = assign_event_label_lanes(events, x_min, x_max)
    if not placed:
        return 0
    ax = axes[0]
    fig.text(0.5, 0.948,
             "Stacked lanes mean events share the same or nearby timestamp; red shading marks active lockout windows.",
             ha="center", va="top", fontsize=7, color="#546e7a")
    y_start = 0.915
    y_step = 0.026
    for event_time, text, color, lane_index in placed:
        x_display = ax.transData.transform((event_time, 0))[0]
        x_figure = fig.transFigure.inverted().transform((x_display, 0))[0]
        x_fraction = (event_time - x_min) / max(1.0, x_max - x_min)
        align = "left" if x_fraction < 0.08 else "right" if x_fraction > 0.92 else "center"
        fig.text(x_figure, y_start - lane_index * y_step, text,
                 ha=align, va="bottom", fontsize=7, color=color)
    return lane_count


def trace_plot_top(lane_count):
    return max(0.55, 0.88 - lane_count * 0.03)


def write_trace_graph(samples, trip_name, trace_name, graph_dir, stimulus=()):
    try:
        import matplotlib.pyplot as plt
    except ImportError:
        return None
    times = [sample[0] * SECONDS_PER_INSTRUCTION * 1000 for sample in samples]
    graph_adc_pins = TRIP_ADC_PINS.get(trip_name, []) if trip_name else []
    graph_rows = ([("digital", "RC1"), ("digital", "RC0"), ("digital", "RC5"), ("digital", "RC6"),
                   ("freq", None)] + [("adc", pin) for pin in graph_adc_pins] +
                  [("digital", "RC7")] + [("digital", pin) for pin in BAND_PINS] +
                  [("stage", None)])
    fig, axes = plt.subplots(len(graph_rows), 1, sharex=True,
                             figsize=(10, max(6, len(graph_rows) * 1.25)))
    axes = list(axes) if hasattr(axes, "__len__") else [axes]
    trip_index = next((index for index, sample in enumerate(samples)
                       if trip_name in TRIP_NAMES and block_reason(sample[2]) == f"FAULT: {trip_name}"), None)
    trip_time = times[trip_index] if trip_index is not None else None
    shutdown_complete_time = times[next((index for index, sample in enumerate(samples)
                                         if trip_name in TRIP_NAMES and
                                         index >= trip_index and
                                         sample[1]["RC5"] == 1 and
                                         sample[1]["RC6"] == 1 and
                                         sample[1]["RC7"] == 1), trip_index)] if trip_index is not None else None
    complete_index = next((index for index, sample in enumerate(samples)
                           if sample[2].get("g_ptt_complete_display_active") == "true" and
                           (sample[1]["RC5"], sample[1]["RC6"], sample[1]["RC7"]) == (0, 0, 0)), None)
    lifecycle = [(times[0], "LCD: STARTUP")]
    ptt_index = next((index for index, sample in enumerate(samples)
                      if sample[2].get("g_ptt_active") == "true"), None)
    if ptt_index is not None:
        lifecycle.append((times[ptt_index], "LCD: PTT REQ"))
    if complete_index is not None:
        lifecycle.append((times[complete_index], "LCD: PTT_COMPLETE"))
        restored_index = next((index for index, sample in enumerate(samples)
                               if index > complete_index and
                               sample[2].get("g_transient_menu_display") == "false"), None)
        if restored_index is not None:
            lifecycle.append((times[restored_index], "LCD: RESTORED USER PAGE"))
    if trip_time is not None:
        lifecycle.append((trip_time, f"LCD: TRIP {trip_name}"))
    for ax, (kind, pin) in zip(axes, graph_rows):
        if kind == "digital":
            ax.step(times, [sample[1][pin] for sample in samples], where="post")
            ax.set_ylim(-0.2, 1.2)
            ax.set_yticks([0, 1])
            label = PIN_LABELS[pin]
        elif kind == "freq":
            # The counter's own reading, WITH the injected stimulus drawn over it: on its own the
            # alternating value/zero looks like a broken counter, and the question "why is it
            # changing so much" is only answerable next to what was fed in.
            ax.step(times, [int(sample[2].get("g_fc_status.frequency_khz") or 0)
                            for sample in samples], where="post")
            scope_trace.draw_stimulus(ax, stimulus)
            label = "g_fc_status.frequency_khz"
        elif kind == "stage":
            # The TX state machine, as `<number> <NAME>` ticks: the number is what the assertions
            # and enum use, the name is what makes it readable.
            ax.step(times, [int(sample[2].get("g_sequence_stage") or 0) for sample in samples],
                    where="post")
            ax.set_ylim(-0.2, 5.2)
            ax.set_yticks(sorted(SEQ_STAGE_NAMES))
            ax.set_yticklabels([stage_name(v) for v in sorted(SEQ_STAGE_NAMES)], fontsize=7)
            label = "g_sequence_stage"
        else:
            # A lean (unkey) sample has no ADC prints: plot a gap rather than crashing on the key.
            values = [sample[3].get(pin, float("nan")) for sample in samples]
            ax.plot(times, values, drawstyle="steps-post")
            ax.set_ylim(-0.2, 5.2)
            label = f"ADC {ADC_LABELS[pin]}"
            if trip_index is not None:
                ax.annotate(f"{values[trip_index]:.3f} V", (times[trip_index], values[trip_index]),
                            xytext=(8, 4), textcoords="offset points", fontsize=8)
        ax.set_ylabel(f"{pin or 'stage'}\n{label}", rotation=0, labelpad=42, va="center")
        ax.grid(True, alpha=0.3)
    reasons = [block_reason(sample[2]) for sample in samples]
    span_start = 0
    span_reason = reasons[0]
    spans = []
    for index, reason in enumerate(reasons[1:], 1):
        if reason != span_reason:
            if span_reason:
                spans.append((times[span_start], times[index], span_reason))
            span_start, span_reason = index, reason
    if span_reason:
        spans.append((times[span_start], times[-1], span_reason))
    for start, end, reason in spans:
        for ax in axes:
            ax.axvspan(start, end, color="red", alpha=0.12)
    for marker_time, marker_label in lifecycle:
        axes[0].axvline(marker_time, color="steelblue", linestyle="-.", alpha=0.45)
    if trip_time is not None:
        axes[0].axvline(trip_time, color="red", linestyle="--", alpha=0.6)
    events = [(time, label, "steelblue") for time, label in lifecycle]
    events += [(span_start, reason, "red") for span_start, _end, reason in spans]
    if trip_time is not None:
        events += [(trip_time, "TX_VCC HIGH (immediate)", "red"),
                   (shutdown_complete_time, "RELAYS HIGH (+5 ms)", "red"),
                   (shutdown_complete_time, "TX_BIAS HIGH (+5 ms)", "red")]
    axes[0].set_xlim(0, times[-1])
    axes[-1].set_xlabel("time (ms, approx)")
    # The timebase is drawn across the TOP of every trace as well (user instruction, 2026-09-25):
    # a tall stack of lanes otherwise leaves the only time axis at the very bottom, unreadable on a
    # thumbnail and off-screen when the lane of interest is at the top.
    scope_trace.add_top_time_axis(axes, times)
    title = f"PTT sequencing with {trip_name} trip (simulated)" if trip_name else "PTT assert/release sequencing (simulated)"
    fig.suptitle(title, y=0.985)
    _placed, lane_count = assign_event_label_lanes(events, times[0], times[-1])
    fig.tight_layout(rect=(0, 0, 1, trace_plot_top(lane_count)))
    draw_event_labels_after_layout(fig, axes, events, times[0], times[-1])
    graph_path = graph_dir / f"{trace_name}.png"
    fig.savefig(graph_path, dpi=120)
    plt.close(fig)
    return graph_path


def main():
    global BAND_FILTERED
    test_mode = "--test" in sys.argv[1:]
    if "--quick-bands" in sys.argv[1:]:
        BAND_TESTS[:] = [("40m", 7000, 3)]
    trip_name = "TEMPERATURE" if "--temperature-trip" in sys.argv[1:] else None
    if "--swr1-1p5" in sys.argv[1:]:
        trip_name = "SWR1_1P5"
    if "--trip" in sys.argv[1:]:
        trip_name = sys.argv[sys.argv.index("--trip") + 1].upper()
    if trip_name is not None and trip_name not in TRIP_NAMES | NON_TRIP_NAMES:
        sys.exit(f"error: unknown trip {trip_name}")
    temperature_trip = trip_name == "TEMPERATURE"
    # `--bands 80m,40m` restricts the whole run to those bands (see BAND_FILTERED).
    bands_argument = _argument_value("--bands")
    if bands_argument is not None:
        wanted = [name.strip() for name in bands_argument.split(",") if name.strip()]
        known = {entry[0]: entry for entry in ALL_BAND_TESTS}
        unknown = [name for name in wanted if name not in known]
        if unknown:
            sys.exit(f"error: unknown --bands {unknown}; known: " + ", ".join(known))
        BAND_TESTS[:] = [known[name] for name in wanted]
        BAND_FILTERED = True
    if "--suite" in sys.argv[1:]:
        scenario_names = [None, "TEMPERATURE", "SWR1", "SWR2", "HWFAULT",
                          "CURRENT", "OVERDRIVE", "DRAIN", "SWR1_1P5", "FREQ_CTR",
                          "FREQ_CTR_FAIL", "SELFTEST_BAD_BAND", "SELFTEST_TX_SENSE",
                          "SELFTEST_REL_STUCK", "SELF_TEST_DIAG", "SELF_TEST_DIAG_STUCK"]
        if "--quick-bands" in sys.argv[1:]:
            scenario_names = [None, "FREQ_CTR", "FREQ_CTR_FAIL"]
        # Debugging shortcut: run ONLY the named scenarios, in the written order, through exactly
        # this code path. The full suite is ~350-400 s on Windows, so re-running it to look at one
        # failing scenario is the wrong instrument - and a hand-built slice silently diverges from
        # the suite (different cadence, different neighbours). Names are the suite's own labels
        # (`base` for the plain PTT scenario); an unknown name is an error, not a silent no-op.
        only = _argument_value("--only")
        if only is not None:
            wanted = [name.strip() for name in only.split(",") if name.strip()]
            known = {_scenario_label(name): name for name in scenario_names}
            unknown = [name for name in wanted if name not in known]
            if unknown:
                sys.exit(f"error: unknown --only scenario(s) {unknown}; known: "
                         + ", ".join(sorted(known)))
            scenario_names = [known[name] for name in wanted]
        suite_lines = []
        # Per-scenario stimulus, so each scenario's graph can show what its counter was fed.
        scenario_stimuli = {}
        for scenario in scenario_names:
            scenario_lines = build_script(trip_name=scenario).splitlines()
            record_stimulus("\n".join(scenario_lines))
            scenario_stimuli[scenario] = list(STIMULUS)
            # Re-emit device/hwtool/program for EVERY scenario. MDB `reset` does NOT clear RAM,
            # so the previous scenario's frequency-counter state leaked across and FREQ_CTR_FAIL
            # "saw" the prior 40m injection (frequency_khz=6963) and keyed the amplifier.
            # Re-programming re-runs crt0, which zeroes .bss/.data and starts the scenario clean.
            suite_lines.extend(scenario_lines[:-1])  # drop the trailing "quit"
        suite_lines.append("quit")
        raw_output = run_mdb(mdb_path=find_mdb(), script="\n".join(suite_lines))
        # Keep the raw transcript beside the CSVs. Without it, a failed scenario split is
        # undiagnosable after the fact: the CSV is only written once validation has already
        # passed, so a failure leaves NO trace of what the harness actually saw (this cost a
        # whole session on 2026-09-22, and led to two wrong diagnoses of the firmware).
        try:
            debug_path = Path(__file__).resolve().parent.parent.parent / "_build" / "My_Pic_Project" / "sim" / "suite_raw_mdb.log"
            debug_path.parent.mkdir(parents=True, exist_ok=True)
            debug_path.write_text(raw_output, encoding="utf-8", errors="replace")
        except OSError:
            pass
        groups = split_scenarios(raw_output, len(scenario_names))
        out_dir = REPO_ROOT / "_build" / "My_Pic_Project" / "sim"
        csv_dir = out_dir / "csv"
        graph_dir = out_dir / "graphs"
        csv_dir.mkdir(parents=True, exist_ok=True)
        graph_dir.mkdir(parents=True, exist_ok=True)
        # Scenario 0 (plain PTT): write its trace/graph on failure too, so a failure here leaves
        # the same visual evidence as every later scenario (the finally clause is what survives an
        # AssertionError).
        for scenario, (_, scenario_samples) in zip(scenario_names, groups):
            # Validation sees the whole scenario (band coverage must still be judged on all of it),
            # but the TRACE stops right after the firmware flags the undefined state: validation and
            # tracing end at the flag, so a failure graph is not 400 ms of aftermath.
            full_samples = scenario_samples
            trace_name = (f"{_scenario_label(scenario).lower()}_trip_trace"
                          if scenario in TRIP_NAMES else f"{_scenario_label(scenario).lower()}_trace")
            if scenario is None:
                trace_name = "ptt_trace"
            try:
                validate_scenario(scenario, full_samples)
            except Exception as exc:
                scenario_samples = truncate_at_unkeyable(full_samples)
                # A failed scenario writes its own scope trace and opens it (see scope_trace):
                # the assertion says WHICH check failed, the trace says what the firmware was
                # doing, and the note under it says what the test was for and what the panel
                # would be showing at that moment.
                scope_trace.on_failure(
                    scenario_samples, trace_name, graph_dir,
                    f"FAILED: {_scenario_label(scenario)} scenario",
                    events=_scope_events(scenario_samples, scenario),
                    stimulus=stimulus_spans(scenario_samples, scenario_stimuli[scenario]),
                    **_failure_context(scenario_samples, scenario, exc))
                raise
            finally:
                # Write this scenario's trace and graph WHETHER IT PASSED OR NOT. A failing
                # scenario is exactly the one whose waveform you need to see, and letting the
                # assertion abort before the write meant the failure left no visual evidence at
                # all - the opposite of useful. The finally clause is what guarantees the graph
                # survives an AssertionError.
                scenario_samples = truncate_at_unkeyable(full_samples)
                write_trace_csv(scenario_samples, trace_name, csv_dir)
                write_trace_graph(scenario_samples, scenario, trace_name, graph_dir,
                                  stimulus=stimulus_spans(scenario_samples,
                                                          scenario_stimuli[scenario]))
            print(f"SUITE_SCENARIO_PASS {_scenario_label(scenario)}", flush=True)
            _describe_scenario_pass(scenario, full_samples)
            if scenario in SELFTEST_SCENARIOS:
                # A fatal fault: render the scope trace WITH the reconstructed FAULT: panel and open
                # it, so the operator sees both what happened and what the LCD would be showing when
                # the amplifier unkeys itself (user instruction, 2026-09-25).
                flagged = [s for s in scenario_samples if s[2].get("g_selftest_failed") == "true"]
                if flagged:
                    panel_path = scope_trace.render_scope(
                        scenario_samples,
                        f"{_scenario_label(scenario)}: fatal fault, RF path opened",
                        graph_dir / f"{trace_name}_scope.png",
                        events=_scope_events(scenario_samples, scenario),
                        lcd_state=flagged[0][2],
                        stimulus=stimulus_spans(scenario_samples, scenario_stimuli[scenario]),
                        lcd_caption="first self-test flagged sample",
                        check=SCENARIO_CHECKS.get(scenario, SCENARIO_CHECKS[None]),
                        observed=_observed_summary(scenario_samples, scenario),
                    )
                    scope_trace.show(panel_path)
        # Band-selection safety invariants (docs/first-dit-band-detection.md) over every
        # scenario: the LPF relays must never move while the amplifier is keyed, the amplifier
        # must never be keyed on a band that is not locked, and the band relays must always be
        # switched before the T/R relay closes (never hot-switch the band relay).
        for scenario, (_, scenario_samples) in zip(scenario_names, groups):
            label = _scenario_label(scenario)
            if scenario in ("SELFTEST_REL_STUCK", "SELF_TEST_DIAG", "SELF_TEST_DIAG_STUCK"):
                # These scenarios deliberately assert TX/TX_VCC/TX_BIAS (or hold one stuck) while the
                # amplifier is in fact cold, so the pin-level "keyed" proxy the band invariants use
                # reads keyed at moments when no transmission exists. SELFTEST_REL_STUCK holds a bias
                # pin stuck (the fault itself); SELF_TEST_DIAG walks the outputs and the sequencer on
                # purpose with PTT never active. The band-switching safety is proven by the
                # base/FREQ_CTR scenarios; the fault/diagnostic verdict is asserted by validate_selftest
                # / validate_diag. The band invariants are meaningless over deliberately-driven pins.
                continue
            for line in invariants.validate_keyed_band_invariants(scenario_samples, label):
                print(line)
            for line in invariants.validate_band_changes_are_cold(scenario_samples, label):
                print(line)
            for line in invariants.validate_t_r_closes_only_after_band_settle(
                    scenario_samples, label):
                print(line)
        # A passing run still has to say WHICH scenarios ran and what each was testing for, not
        # just "no failure text to report" (user instruction, 2026-09-26). The per-scenario observed
        # summaries are inline above; this is the readable block at the end of the log.
        print("===== SCENARIOS RUN (all passed) =====")
        for scenario in scenario_names:
            label = _scenario_label(scenario)
            check = SCENARIO_CHECKS.get(scenario, SCENARIO_CHECKS[None])
            print(f"  {label}: {check}")
        print("===== END SCENARIOS =====")
        print(f"PTT suite passed: {len(scenario_names)} scenarios in one MDB session")
        return
    if not ELF_PATH.exists():
        sys.exit(f"error: {ELF_PATH} not found - build firmware first (build_firmware.ps1/.sh)")
    mdb_path = find_mdb()
    script = build_script(trip_name=trip_name)
    record_stimulus(script)
    output = run_mdb(mdb_path, script)
    samples = parse_trace(output)
    if not samples:
        sys.exit("error: no samples parsed from mdb output - dumping raw output:\n" + output[-4000:])
    # Everything after the undefined/unkeyable flag is aftermath: the test and the trace end there.
    samples = truncate_at_unkeyable(samples)
    if test_mode:
        validate_sequence(samples)
        print("PTT sequencing test passed")
    if trip_name:
        try:
            if trip_name in TRIP_NAMES:
                validate_trip(samples, trip_name)
            else:
                validate_swr1_1p5(samples)
        except Exception as exc:
            scope_trace.on_failure(
                samples, f"{trip_name.lower()}_trip_trace",
                REPO_ROOT / "_build" / "My_Pic_Project" / "sim" / "graphs",
                f"FAILED: {trip_name} scenario",
                events=_scope_events(samples, trip_name),
                stimulus=stimulus_spans(samples),
                **_failure_context(samples, trip_name, exc))
            raise

    out_dir = REPO_ROOT / "_build" / "My_Pic_Project" / "sim"
    csv_dir = out_dir / "csv"
    graph_dir = out_dir / "graphs"
    csv_dir.mkdir(parents=True, exist_ok=True)
    graph_dir.mkdir(parents=True, exist_ok=True)
    trace_name = f"{trip_name.lower()}_trip_trace" if trip_name else "ptt_trace"
    csv_path = csv_dir / f"{trace_name}.csv"
    with open(csv_path, "w") as f:
        f.write("time_s," + ",".join(PIN_LABELS[p] for p in PINS) +
            "," + ",".join(f"ADC_{pin}_V" for pin in ADC_PINS) +
            ",g_ptt_active,g_sequence_stage,stage_name,g_state,block_reason\n")
        for instr_count, vals, state, adc_voltages in samples:
            t = instr_count * SECONDS_PER_INSTRUCTION
            reason = block_reason(state) or ""
            stage = state.get('g_sequence_stage', "")
            f.write(f"{t:.6f}," + ",".join(str(vals.get(pin, "")) for pin in PINS) +
                "," + ",".join(f"{adc_voltages[pin]:.3f}" if pin in adc_voltages else ""
                                for pin in ADC_PINS) +
                f",{state.get('g_ptt_active', '')},{stage},{stage_name(stage)},"
                f"{state.get('g_state', '')},{reason}\n")
    print(f"Wrote {csv_path} ({len(samples)} samples)")

    # Print console FAULT/blocking-reason transitions so "why can't PTT key up" is obvious
    # without having to read the plot.
    last_reason = object()
    for instr_count, _vals, state, _adc_voltages in samples:
        reason = block_reason(state)
        if reason != last_reason:
            t = instr_count * SECONDS_PER_INSTRUCTION * 1000
            print(f"t={t:8.2f}ms  {reason if reason else 'PTT OK (no block)'}")
            last_reason = reason

    try:
        import matplotlib.pyplot as plt
    except ImportError:
        print("matplotlib not installed; skipping PNG (pip install matplotlib)")
        return

    times = [s[0] * SECONDS_PER_INSTRUCTION * 1000 for s in samples]  # ms
    reasons = [block_reason(s[2]) for s in samples]

    # Contiguous [start, end, reason] spans where PTT/TX is blocked, for shading/labeling.
    block_spans = []
    span_start = None
    span_reason = None
    for t, reason in zip(times, reasons):
        if reason != span_reason:
            if span_reason is not None:
                block_spans.append((span_start, t, span_reason))
            span_start, span_reason = t, reason
    if span_reason is not None:
        block_spans.append((span_start, times[-1], span_reason))

    graph_adc_pins = TRIP_ADC_PINS.get(trip_name, []) if trip_name else []
    graph_rows = ([("digital", "RC1"), ("digital", "RC0"), ("digital", "RC5"), ("digital", "RC6")] +
                  [("adc", pin) for pin in graph_adc_pins] +
                  [("digital", "RC7")] + [("digital", pin) for pin in BAND_PINS] +
                  [("stage", None)])
    fig, axes = plt.subplots(len(graph_rows), 1, sharex=True,
                             figsize=(10, max(6, len(graph_rows) * 1.25)))
    axes = list(axes) if hasattr(axes, "__len__") else [axes]
    trip_time = None
    shutdown_complete_time = None
    trip_index = None
    if trip_name in TRIP_NAMES:
        trip_index = next(index for index, sample in enumerate(samples)
                          if block_reason(sample[2]) == f"FAULT: {trip_name}")
        trip_time = times[trip_index]
        shutdown_complete_time = times[next(index for index, sample in enumerate(samples)
                                            if sample[2].get("g_trip_shutdown_active") == "false" and
                                            block_reason(sample[2]) == f"FAULT: {trip_name}")]
    lifecycle = [(times[0], "LCD: STARTUP")]
    ptt_index = next((index for index, sample in enumerate(samples)
                      if sample[2].get("g_ptt_active") == "true"), None)
    if ptt_index is not None:
        lifecycle.append((times[ptt_index], "LCD: PTT REQ"))
    complete_index = next((index for index, sample in enumerate(samples)
                           if sample[2].get("g_ptt_complete_display_active") == "true" and
                           (sample[1]["RC5"], sample[1]["RC6"], sample[1]["RC7"]) == (0, 0, 0)), None)
    if complete_index is not None:
        lifecycle.append((times[complete_index], "LCD: PTT_COMPLETE"))
    if trip_time is not None:
        lifecycle.append((trip_time, f"LCD: TRIP {trip_name}"))
    restored_index = next((index for index, sample in enumerate(samples)
                           if complete_index is not None and index > complete_index and
                           sample[2].get("g_transient_menu_display") == "false"), None)
    if restored_index is not None:
        lifecycle.append((times[restored_index], "LCD: RESTORED USER PAGE"))
    for ax, (kind, pin) in zip(axes, graph_rows):
        if kind == "digital":
            values = [s[1][pin] for s in samples]
            ax.step(times, values, where="post")
            ax.set_ylim(-0.2, 1.2)
            ax.set_yticks([0, 1])
            label = PIN_LABELS[pin]
        elif kind == "stage":
            ax.step(times, [int(s[2].get("g_sequence_stage") or 0) for s in samples], where="post")
            ax.set_ylim(-0.2, 5.2)
            ax.set_yticks(sorted(SEQ_STAGE_NAMES))
            ax.set_yticklabels([stage_name(v) for v in sorted(SEQ_STAGE_NAMES)], fontsize=7)
            label = "g_sequence_stage"
        else:
            # A lean (unkey) sample has no ADC prints: plot a gap rather than crashing on the key.
            values = [s[3].get(pin, float("nan")) for s in samples]
            ax.plot(times, values, drawstyle="steps-post")
            ax.set_ylim(-0.2, 5.2)
            label = f"ADC {ADC_LABELS[pin]}"
            if trip_index is not None:
                ax.annotate(f"{values[trip_index]:.3f} V", (trip_time, values[trip_index]),
                            xytext=(8, 4), textcoords="offset points", fontsize=8)
        ax.set_ylabel(f"{pin or 'stage'}\n{label}", rotation=0, labelpad=42, va="center")
        ax.grid(True, alpha=0.3)
        for start, end, reason in block_spans:
            ax.axvspan(start, end, color="red", alpha=0.12)
        if trip_name in TRIP_NAMES:
            ax.axvline(trip_time, color="red", linestyle="--", alpha=0.6)
            ax.axvline(shutdown_complete_time, color="orange", linestyle=":", alpha=0.7)
    for marker_time, marker_label in lifecycle:
        axes[0].axvline(marker_time, color="steelblue", linestyle="-.", alpha=0.45)
    events = [(time, label, "steelblue") for time, label in lifecycle]
    events += [(start, reason, "red") for start, _end, reason in block_spans]
    if trip_name in TRIP_NAMES:
        events += [(trip_time, "TX_VCC HIGH (immediate)", "red"),
                   (shutdown_complete_time, "RELAYS HIGH (+5 ms)", "red"),
                   (shutdown_complete_time, "TX_BIAS HIGH (+5 ms)", "red")]
    axes[0].set_xlim(0, times[-1])
    axes[-1].set_xlabel("time (ms, approx)")
    # Timebase across the top too - see the note in write_trace_graph.
    scope_trace.add_top_time_axis(axes, times)
    title = ("PTT sequencing with SWR1 1.5:1 no-trip (simulated)" if trip_name == "SWR1_1P5"
             else f"PTT sequencing with {trip_name} trip (simulated)" if trip_name
             else "PTT assert/release sequencing (simulated)")
    fig.suptitle(title, y=0.985)
    _placed, lane_count = assign_event_label_lanes(events, times[0], times[-1])
    fig.tight_layout(rect=(0, 0, 1, trace_plot_top(lane_count)))
    draw_event_labels_after_layout(fig, axes, events, times[0], times[-1])
    png_path = graph_dir / f"{trace_name}.png"
    fig.savefig(png_path, dpi=120)
    print(f"Wrote {png_path}")
if __name__ == "__main__":
    try:
        main()
    except Exception as exc:      # noqa: BLE001 - anything at all must leave a failure text behind
        write_crash_report(exc)
        raise

